package com.wikigearsetups;

import com.wikigearsetups.layout.LayoutStyle;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(WikiGearSetupsConfig.GROUP)
public interface WikiGearSetupsConfig extends Config
{
	String GROUP = "wikigearsetups";

	enum MissingGearBehavior
	{
		OMIT("Hide — only gear I own"),
		SHOW_BEST_UNOWNED("Show as a goal");

		private final String label;

		MissingGearBehavior(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "missingGearBehavior",
		name = "Unowned recommendations",
		description = "For a slot where you own none of the recommended items: "
			+ "'Show as a goal' fills it with the wiki's best pick, highlighted as unowned, "
			+ "so you can see what to aim for; 'Hide' leaves it empty so the tab holds only gear you own.",
		position = 0
	)
	default MissingGearBehavior missingGearBehavior()
	{
		return MissingGearBehavior.SHOW_BEST_UNOWNED;
	}

	@ConfigItem(
		keyName = "layoutStyle",
		name = "Layout shape",
		description = "Arrange imported tabs like the worn equipment screen (inventory-ready), or as packed rows",
		position = 1
	)
	default LayoutStyle layoutStyle()
	{
		return LayoutStyle.EQUIPMENT_SCREEN;
	}

	@ConfigItem(
		keyName = "defaultToWikiBis",
		name = "Start in Wiki BIS view",
		description = "Open each page with 'Show wiki BIS' already ticked, so setups show the wiki's ideal "
			+ "gear instead of adapting to your bank. Off shows the setup built from what you own.",
		position = 2
	)
	default boolean defaultToWikiBis()
	{
		return false;
	}

	@ConfigItem(
		keyName = "confirmOverwrite",
		name = "Confirm before overwriting",
		description = "Ask before an import replaces an existing bank tag. Turn off to import without the "
			+ "prompt — a tab you arranged by hand can't be recovered, so leave this on unless you re-import a lot.",
		position = 3
	)
	default boolean confirmOverwrite()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeExtras",
		name = "Extra owned gear",
		description = "Place owned alternatives and situational switches the wiki mentions below the main "
			+ "layout. Turn off for a tab of just the chosen loadout.",
		position = 4
	)
	default boolean includeExtras()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trimEmptySpace",
		name = "Trim space below layout",
		description = "Stop the bank scrolling past the end of a tab this plugin created. Bank Tags fills "
			+ "every unused slot in your whole bank with an empty drop target, so a big bank scrolls through "
			+ "a lot of nothing. Turn off to keep the full scroll range for dragging items in.",
		position = 5
	)
	default boolean trimEmptySpace()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tagPrefix",
		name = "Tag name prefix",
		description = "Prepended to every tab this plugin creates (e.g. 'wgs') so they sort together in Bank "
			+ "Tags and never collide with your own tabs. Leave blank for no prefix.",
		position = 6
	)
	default String tagPrefix()
	{
		return "";
	}

}

package com.wikigearsetups;

import com.google.inject.Binder;
import com.google.inject.Provides;
import com.wikigearsetups.bank.BankStateCache;
import com.wikigearsetups.items.ClientItemNameIndex;
import com.wikigearsetups.items.ItemNameIndex;
import com.wikigearsetups.layout.LayoutScrollTrimmer;
import com.wikigearsetups.ui.WikiGearSetupsPanel;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Wiki Gear Setups",
	description = "Import recommended gear setups from the OSRS Wiki as bank tag layouts, built from the gear you own",
	tags = {"bank", "tag", "layout", "gear", "equipment", "wiki", "setup"}
)
@PluginDependency(BankTagsPlugin.class)
public class WikiGearSetupsPlugin extends Plugin
{
	/**
	 * Shown in the disclaimer footer so a bug report can name the build.
	 *
	 * Hard-coded rather than derived from the build: the hub's `standard`
	 * build mode replaces build.gradle, so anything gradle injected at
	 * package time would be lost. Keep in step with build.gradle and
	 * runelite-plugin.properties when releasing.
	 */
	public static final String VERSION = "1.0";

	@Inject
	private Client client;

	@Inject
	private ClientItemNameIndex itemNameIndex;

	@Inject
	private BankStateCache bankStateCache;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WikiGearSetupsPanel panel;

	@Inject
	private LayoutScrollTrimmer layoutScrollTrimmer;

	private NavigationButton navButton;

	@Override
	public void configure(Binder binder)
	{
		binder.bind(ItemNameIndex.class).to(ClientItemNameIndex.class);
	}

	@Override
	protected void startUp()
	{
		BufferedImage icon = ImageUtil.loadImageResource(WikiGearSetupsPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Wiki Gear Setups")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			itemNameIndex.ensureBuilt();
			bankStateCache.loadSnapshot();
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			itemNameIndex.ensureBuilt();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// fires once the RS profile is known post-login, and on world hops
		// across profile boundaries (e.g. leagues) — reload the right snapshot
		bankStateCache.loadSnapshot();
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		// after the bank has finished building, so core Bank Tags has already
		// laid the tab out and the vanilla scrollbar height is in place
		if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			layoutScrollTrimmer.onBankBuilt();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			bankStateCache.updateFromContainer(event.getItemContainer());
		}
	}

	@Provides
	WikiGearSetupsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WikiGearSetupsConfig.class);
	}
}

package com.wikigearsetups.bank;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.wikigearsetups.WikiGearSetupsConfig;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

/**
 * The bank is only readable while its widget is open, so ownership checks
 * run against a snapshot: captured whenever the bank container changes and
 * persisted per RuneScape profile (so alts and leagues don't cross-pollute).
 * Inventory and equipment are always readable and are merged in live.
 */
@Slf4j
@Singleton
public class BankStateCache
{
	static final String SNAPSHOT_KEY = "bankSnapshot";
	private static final Type SNAPSHOT_TYPE = new TypeToken<Map<Integer, Integer>>()
	{
	}.getType();

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;

	private volatile Map<Integer, Integer> bank = Collections.emptyMap();
	private volatile boolean snapshotLoaded;

	@Inject
	public BankStateCache(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Call with the bank container whenever it changes (bank must be open). */
	public void updateFromContainer(ItemContainer container)
	{
		Map<Integer, Integer> snapshot = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				snapshot.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		bank = snapshot;
		snapshotLoaded = true;
		configManager.setRSProfileConfiguration(WikiGearSetupsConfig.GROUP, SNAPSHOT_KEY, serialize(gson, snapshot));
		log.debug("Bank snapshot updated: {} distinct items", snapshot.size());
	}

	/** Loads the persisted snapshot for the current RS profile, if any. */
	public void loadSnapshot()
	{
		String json = configManager.getRSProfileConfiguration(WikiGearSetupsConfig.GROUP, SNAPSHOT_KEY);
		Map<Integer, Integer> snapshot = deserialize(gson, json);
		if (snapshot != null)
		{
			bank = snapshot;
			snapshotLoaded = true;
			log.debug("Bank snapshot loaded: {} distinct items", snapshot.size());
		}
		else
		{
			bank = Collections.emptyMap();
			snapshotLoaded = false;
		}
	}

	/** False until the player has opened their bank once (this profile). */
	public boolean hasSnapshot()
	{
		return snapshotLoaded;
	}

	public Map<Integer, Integer> getBankItems()
	{
		return Collections.unmodifiableMap(bank);
	}

	/**
	 * All item ids the player owns: bank snapshot plus live inventory and
	 * equipment. Must be called on the client thread (reads item containers).
	 *
	 * Group Ironman shared group storage is deliberately not included — only
	 * the player's own bank, inventory and worn gear count as owned.
	 */
	public Set<Integer> ownedItemIds()
	{
		Set<Integer> owned = new HashSet<>(bank.keySet());
		addContainer(owned, client.getItemContainer(InventoryID.INV));
		addContainer(owned, client.getItemContainer(InventoryID.WORN));
		return owned;
	}

	private static void addContainer(Set<Integer> owned, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				owned.add(item.getId());
			}
		}
	}

	static String serialize(Gson gson, Map<Integer, Integer> snapshot)
	{
		return gson.toJson(snapshot, SNAPSHOT_TYPE);
	}

	static Map<Integer, Integer> deserialize(Gson gson, String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, SNAPSHOT_TYPE);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Discarding corrupt bank snapshot", e);
			return null;
		}
	}
}

package com.wikigearsetups.bank;

import com.wikigearsetups.items.ItemNames;
import com.wikigearsetups.wiki.EquipSlot;
import com.wikigearsetups.wiki.GearSetup;
import com.wikigearsetups.wiki.RankedItem;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Example loadouts name one concrete item per slot, which alone would lose
 * ownership personalization. Most raid pages also carry ranked
 * recommendation tables — each example item is looked up in those ladders
 * and its slot gains the ladder as fallback alternatives. The example item
 * stays first (owned → placed, unowned → the goal), so tier intent is
 * preserved while unowned slots degrade to the best gear the player has.
 *
 * The anchor lookup also picks the right style implicitly: a melee example
 * weapon is only found in the melee setup's weapon ladder.
 */
public final class ExampleGearEnricher
{
	private ExampleGearEnricher()
	{
	}

	public static GearSetup enrich(GearSetup example, List<GearSetup> rankedSetups)
	{
		if (rankedSetups == null || rankedSetups.isEmpty())
		{
			return example;
		}
		Map<EquipSlot, List<RankedItem>> slots = new EnumMap<>(EquipSlot.class);
		for (Map.Entry<EquipSlot, List<RankedItem>> entry : example.getSlots().entrySet())
		{
			RankedItem anchor = entry.getValue().get(0);
			List<RankedItem> merged = new ArrayList<>();
			merged.add(anchor);
			List<RankedItem> ladder = findLadder(entry.getKey(), anchor, rankedSetups);
			if (ladder != null)
			{
				String anchorName = ItemNames.normalize(anchor.getName());
				for (RankedItem alternative : ladder)
				{
					if (!ItemNames.normalize(alternative.getName()).equals(anchorName))
					{
						merged.add(alternative);
					}
				}
			}
			slots.put(entry.getKey(), merged);
		}
		return new GearSetup(example.getStyleLabel(), slots);
	}

	/** The first ranked slot list containing the anchor item, or null. */
	private static List<RankedItem> findLadder(EquipSlot slot, RankedItem anchor, List<GearSetup> rankedSetups)
	{
		String anchorName = ItemNames.normalize(anchor.getName());
		for (GearSetup setup : rankedSetups)
		{
			List<RankedItem> list = setup.getSlots().get(slot);
			if (list == null)
			{
				continue;
			}
			for (RankedItem item : list)
			{
				if (ItemNames.normalize(item.getName()).equals(anchorName))
				{
					return list;
				}
			}
		}
		return null;
	}
}

package com.wikigearsetups.bank;

import lombok.Value;

/** One inventory slot resolved to a concrete item id. slot is 0-based (0-27). */
@Value
public class InventoryPick
{
	int slot;
	int itemId;
	boolean owned;
}

package com.wikigearsetups.bank;

import com.wikigearsetups.wiki.InventorySetup;
import java.util.List;
import lombok.Value;

/**
 * missingCount covers inventory slots and runes together (one per slot);
 * missingNames is the deduplicated wiki names behind that count. runePicks
 * use slot = index within the rune list (0-3), not a grid position.
 */
@Value
public class InventoryResolution
{
	InventorySetup setup;
	List<InventoryPick> picks;
	List<InventoryPick> runePicks;
	List<String> unresolvedNames;
	List<String> missingNames;
	int missingCount;
}

package com.wikigearsetups.bank;

import com.wikigearsetups.WikiGearSetupsConfig.MissingGearBehavior;
import com.wikigearsetups.items.ConsumableGroups;
import com.wikigearsetups.items.ItemNames;
import com.wikigearsetups.items.ItemResolver;
import com.wikigearsetups.items.PlaceholderItems;
import com.wikigearsetups.items.ResolvedItem;
import com.wikigearsetups.wiki.GearSetup;
import com.wikigearsetups.wiki.InventorySetup;
import com.wikigearsetups.wiki.RankedItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Resolves an inventory setup's 28 slots (and its rune pouch) against owned
 * items. Inventory has no ranked alternatives — a slot's item is either
 * owned (place the owned variant), missing (placed only under
 * SHOW_BEST_UNOWNED), or unrecognized (placeholder templates like
 * "Cheap food", reported not placed).
 */
@Singleton
public class InventoryResolver
{
	private final ItemResolver itemResolver;

	@Inject
	public InventoryResolver(ItemResolver itemResolver)
	{
		this.itemResolver = itemResolver;
	}

	public InventoryResolution resolve(InventorySetup setup, Set<Integer> ownedIds, MissingGearBehavior missingBehavior)
	{
		return resolve(setup, ownedIds, missingBehavior, Collections.emptyList());
	}

	/**
	 * {@code rankedSetups} are the page's gear ladders — an unowned switch
	 * item in the inventory (blowpipe, trident) falls back to the best owned
	 * alternative from the ladder that contains it, just like worn gear.
	 */
	public InventoryResolution resolve(InventorySetup setup, Set<Integer> ownedIds,
		MissingGearBehavior missingBehavior, List<GearSetup> rankedSetups)
	{
		return resolve(setup, ownedIds, missingBehavior, rankedSetups, PickStrategy.BEST_OWNED);
	}

	public InventoryResolution resolve(InventorySetup setup, Set<Integer> ownedIds,
		MissingGearBehavior missingBehavior, List<GearSetup> rankedSetups, PickStrategy strategy)
	{
		List<InventoryPick> picks = new ArrayList<>();
		List<InventoryPick> runePicks = new ArrayList<>();
		Set<String> unresolved = new LinkedHashSet<>();
		Set<String> missingNames = new LinkedHashSet<>();
		int[] missing = {0};

		List<String> slots = setup.getSlots();
		for (int i = 0; i < slots.size(); i++)
		{
			resolveOne(slots.get(i), i, ownedIds, missingBehavior, rankedSetups,
				picks, unresolved, missingNames, missing, strategy);
		}
		List<String> runes = setup.getRunes();
		for (int i = 0; i < runes.size(); i++)
		{
			resolveOne(runes.get(i), i, ownedIds, missingBehavior, Collections.emptyList(),
				runePicks, unresolved, missingNames, missing, strategy);
		}

		return new InventoryResolution(setup, picks, runePicks,
			new ArrayList<>(unresolved), new ArrayList<>(missingNames), missing[0]);
	}

	private void resolveOne(String name, int slot, Set<Integer> ownedIds, MissingGearBehavior missingBehavior,
		List<GearSetup> rankedSetups, List<InventoryPick> out, Set<String> unresolved,
		Set<String> missingNames, int[] missing, PickStrategy strategy)
	{
		if (name.isEmpty())
		{
			return;
		}
		Optional<ResolvedItem> resolved = itemResolver.resolve(name);
		if (!resolved.isPresent())
		{
			resolvePlaceholder(name, slot, ownedIds, missingBehavior, out, unresolved,
				missingNames, missing, strategy);
			return;
		}

		Integer ownedId = firstOwned(resolved.get(), ownedIds);
		if (ownedId != null)
		{
			out.add(new InventoryPick(slot, ownedId, true));
			return;
		}

		// showing the wiki's own list: place it unowned and count it, rather
		// than substituting something the player happens to have
		if (strategy == PickStrategy.TOP_RECOMMENDATION)
		{
			missing[0]++;
			missingNames.add(name);
			out.add(new InventoryPick(slot, resolved.get().getPrimaryId(), false));
			return;
		}

		Integer substitute = substituteFor(name, ownedIds, rankedSetups);
		if (substitute != null)
		{
			out.add(new InventoryPick(slot, substitute, true));
			return;
		}

		missing[0]++;
		missingNames.add(name);
		if (missingBehavior == MissingGearBehavior.SHOW_BEST_UNOWNED)
		{
			out.add(new InventoryPick(slot, resolved.get().getPrimaryId(), false));
		}
	}

	/**
	 * Owned stand-in for an unowned inventory item: first the gear ladder
	 * containing it (switch items, style-correct by construction), then its
	 * consumable class (best owned food for an unowned shark).
	 */
	private Integer substituteFor(String name, Set<Integer> ownedIds, List<GearSetup> rankedSetups)
	{
		String normalized = ItemNames.normalize(name);
		for (GearSetup setup : rankedSetups)
		{
			for (List<RankedItem> ladder : setup.getSlots().values())
			{
				boolean anchored = false;
				for (RankedItem item : ladder)
				{
					if (ItemNames.normalize(item.getName()).equals(normalized))
					{
						anchored = true;
						break;
					}
				}
				if (!anchored)
				{
					continue;
				}
				for (RankedItem item : ladder)
				{
					Optional<ResolvedItem> resolved = itemResolver.resolve(item.getName());
					if (resolved.isPresent())
					{
						Integer owned = firstOwned(resolved.get(), ownedIds);
						if (owned != null)
						{
							return owned;
						}
					}
				}
			}
		}
		for (String candidate : ConsumableGroups.groupFor(name))
		{
			Optional<ResolvedItem> resolved = itemResolver.resolve(candidate);
			if (resolved.isPresent())
			{
				Integer owned = firstOwned(resolved.get(), ownedIds);
				if (owned != null)
				{
					return owned;
				}
			}
		}
		return null;
	}

	/**
	 * Placeholder templates ({{Cheap food}}) become whichever concrete
	 * candidate the player owns; failing that, the first candidate as a goal
	 * item under SHOW_BEST_UNOWNED. Unknown placeholders stay unresolved.
	 */
	private void resolvePlaceholder(String name, int slot, Set<Integer> ownedIds,
		MissingGearBehavior missingBehavior, List<InventoryPick> out, Set<String> unresolved,
		Set<String> missingNames, int[] missing, PickStrategy strategy)
	{
		List<String> candidates = PlaceholderItems.candidatesFor(name);
		if (candidates.isEmpty())
		{
			unresolved.add(name);
			return;
		}

		ResolvedItem firstResolvable = null;
		for (String candidate : candidates)
		{
			Optional<ResolvedItem> resolved = itemResolver.resolve(candidate);
			if (!resolved.isPresent())
			{
				continue;
			}
			if (firstResolvable == null)
			{
				firstResolvable = resolved.get();
				// the wiki's own answer for a placeholder is its best
				// candidate, owned or not
				if (strategy == PickStrategy.TOP_RECOMMENDATION)
				{
					Integer owned = firstOwned(firstResolvable, ownedIds);
					if (owned == null)
					{
						missing[0]++;
						missingNames.add(name);
					}
					out.add(new InventoryPick(slot,
						owned != null ? owned : firstResolvable.getPrimaryId(), owned != null));
					return;
				}
			}
			Integer ownedId = firstOwned(resolved.get(), ownedIds);
			if (ownedId != null)
			{
				out.add(new InventoryPick(slot, ownedId, true));
				return;
			}
		}

		if (firstResolvable == null)
		{
			unresolved.add(name);
			return;
		}
		missing[0]++;
		missingNames.add(name);
		if (missingBehavior == MissingGearBehavior.SHOW_BEST_UNOWNED)
		{
			out.add(new InventoryPick(slot, firstResolvable.getPrimaryId(), false));
		}
	}

	private static Integer firstOwned(ResolvedItem resolved, Set<Integer> ownedIds)
	{
		for (int id : resolved.getAcceptableIds())
		{
			if (ownedIds.contains(id))
			{
				return id;
			}
		}
		return null;
	}
}

package com.wikigearsetups.bank;

import com.wikigearsetups.WikiGearSetupsConfig.MissingGearBehavior;
import com.wikigearsetups.items.ItemNames;
import com.wikigearsetups.items.ItemResolver;
import com.wikigearsetups.items.ItemSets;
import com.wikigearsetups.items.ResolvedItem;
import com.wikigearsetups.wiki.EquipSlot;
import com.wikigearsetups.wiki.GearSetup;
import com.wikigearsetups.wiki.RankedItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.IntPredicate;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Walks each slot's ranked alternatives (best first) and picks the first
 * recommendation the player can satisfy, recording the specific owned
 * variant id. Pure logic — callers supply the owned-id set (see
 * {@link BankStateCache#ownedItemIds()}).
 */
@Singleton
public class OwnershipResolver
{
	private final ItemResolver itemResolver;

	@Inject
	public OwnershipResolver(ItemResolver itemResolver)
	{
		this.itemResolver = itemResolver;
	}

	/** Adaptive resolution (BEST_OWNED). */
	public SetupResolution resolve(GearSetup setup, Set<Integer> ownedIds, MissingGearBehavior missingBehavior,
		boolean assumeSlayerTask)
	{
		return resolve(setup, ownedIds, missingBehavior, assumeSlayerTask, PickStrategy.BEST_OWNED);
	}

	public SetupResolution resolve(GearSetup setup, Set<Integer> ownedIds, MissingGearBehavior missingBehavior,
		boolean assumeSlayerTask, PickStrategy strategy)
	{
		Map<EquipSlot, List<String>> unresolved = new EnumMap<>(EquipSlot.class);
		Map<EquipSlot, Set<String>> excluded = new EnumMap<>(EquipSlot.class);
		Map<EquipSlot, SlotPick> pickBySlot = new EnumMap<>(EquipSlot.class);

		for (Map.Entry<EquipSlot, List<RankedItem>> entry : setup.getSlots().entrySet())
		{
			excluded.put(entry.getKey(), new HashSet<>());
			SlotPick pick = resolveSlot(entry.getKey(), entry.getValue(), ownedIds, missingBehavior,
				assumeSlayerTask, excluded.get(entry.getKey()), unresolved, strategy);
			if (pick != null)
			{
				pickBySlot.put(entry.getKey(), pick);
			}
		}

		// A set piece must actually be WORN in this layout, not just banked:
		// owning the full blood moon set doesn't justify the helm when better
		// body/legs win their slots. Excluding a piece can invalidate another
		// set piece, so iterate to a fixpoint (exclusions only grow).
		// Ownership-derived, so it has no meaning when showing the wiki's own
		// pick — an owned set piece must stay put there.
		boolean changed = strategy == PickStrategy.BEST_OWNED;
		while (changed)
		{
			changed = false;
			for (Map.Entry<EquipSlot, List<RankedItem>> entry : setup.getSlots().entrySet())
			{
				SlotPick pick = pickBySlot.get(entry.getKey());
				if (pick == null || !pick.isOwned())
				{
					continue;
				}
				RankedItem item = pick.getItem();
				ItemSets.Requirement requirement = ItemSets.requirementFor(item.getName());
				if (requirement == null
					|| (!requirement.isAlways() && !ItemSets.setConditionalNote(item.getNote()))
					|| setWornInLayout(requirement, pickBySlot, ownedIds))
				{
					continue;
				}
				excluded.get(entry.getKey()).add(item.getName());
				SlotPick replacement = resolveSlot(entry.getKey(), entry.getValue(), ownedIds,
					missingBehavior, assumeSlayerTask, excluded.get(entry.getKey()), null, strategy);
				if (replacement != null)
				{
					pickBySlot.put(entry.getKey(), replacement);
				}
				else
				{
					pickBySlot.remove(entry.getKey());
				}
				changed = true;
			}
		}

		List<SlotPick> picks = new ArrayList<>();
		List<EquipSlot> emptySlots = new ArrayList<>();
		for (Map.Entry<EquipSlot, List<RankedItem>> entry : setup.getSlots().entrySet())
		{
			SlotPick pick = pickBySlot.get(entry.getKey());
			if (pick != null)
			{
				picks.add(pick);
			}
			else
			{
				emptySlots.add(entry.getKey());
			}
		}
		return new SetupResolution(setup, picks, unresolved, emptySlots);
	}

	/**
	 * Resolves one slot: first satisfiable alternative wins; under
	 * SHOW_BEST_UNOWNED an unowned best becomes a goal pick; null when the
	 * slot stays empty. {@code unresolved} is only recorded when non-null so
	 * re-resolution during set stabilization doesn't duplicate entries.
	 */
	private SlotPick resolveSlot(EquipSlot slot, List<RankedItem> alternatives, Set<Integer> ownedIds,
		MissingGearBehavior missingBehavior, boolean assumeSlayerTask,
		Set<String> excludedNames, Map<EquipSlot, List<String>> unresolved, PickStrategy strategy)
	{
		if (strategy == PickStrategy.TOP_RECOMMENDATION)
		{
			return topRecommendation(slot, alternatives, ownedIds, assumeSlayerTask, unresolved);
		}

		RankedItem bestResolvable = null;
		ResolvedItem bestResolved = null;
		// tracked ignoring the set gate, so a slot whose every alternative
		// needs an unowned set still shows the top piece as a goal
		RankedItem bestAnyResolvable = null;
		ResolvedItem bestAnyResolved = null;

		for (int i = 0; i < alternatives.size(); i++)
		{
			RankedItem candidate = alternatives.get(i);
			if (excludedNames.contains(candidate.getName()))
			{
				continue;
			}
			if (!assumeSlayerTask && isSlayerTaskConditional(candidate))
			{
				continue;
			}
			Optional<ResolvedItem> resolved = resolveCandidate(candidate);
			if (!resolved.isPresent())
			{
				if (unresolved != null)
				{
					unresolved.computeIfAbsent(slot, k -> new ArrayList<>()).add(candidate.getName());
				}
				continue;
			}
			if (bestAnyResolvable == null)
			{
				bestAnyResolvable = candidate;
				bestAnyResolved = resolved.get();
			}
			if (!setSatisfied(candidate, ownedIds))
			{
				continue;
			}
			if (bestResolvable == null)
			{
				bestResolvable = candidate;
				bestResolved = resolved.get();
			}

			Integer ownedId = firstOwned(resolved.get(), ownedIds);
			if (ownedId != null)
			{
				return new SlotPick(slot, candidate, ownedId, true, i == 0);
			}
		}

		if (bestResolvable == null)
		{
			bestResolvable = bestAnyResolvable;
			bestResolved = bestAnyResolved;
		}
		if (missingBehavior == MissingGearBehavior.SHOW_BEST_UNOWNED && bestResolvable != null)
		{
			return new SlotPick(slot, bestResolvable, bestResolved.getPrimaryId(), false, true);
		}
		return null;
	}

	/**
	 * Wiki links sometimes point at a page rather than an item ("God
	 * capes#Imbuing"); the display text and picture the template carried are
	 * tried in turn when the primary name resolves to nothing.
	 */
	private Optional<ResolvedItem> resolveCandidate(RankedItem candidate)
	{
		Optional<ResolvedItem> resolved = itemResolver.resolve(candidate.getName());
		if (resolved.isPresent())
		{
			return resolved;
		}
		for (String fallback : candidate.getFallbackNames())
		{
			resolved = itemResolver.resolve(fallback);
			if (resolved.isPresent())
			{
				return resolved;
			}
		}
		return Optional.empty();
	}

	/**
	 * The wiki's own first choice for the slot, ownership only deciding
	 * whether the pick is flagged owned and which variant id is placed —
	 * an owned recolour/upgrade still lands as the player's copy so the tab
	 * stays usable. Set gating is deliberately not consulted: it exists to
	 * adapt to what the player owns, which this strategy ignores.
	 */
	private SlotPick topRecommendation(EquipSlot slot, List<RankedItem> alternatives, Set<Integer> ownedIds,
		boolean assumeSlayerTask, Map<EquipSlot, List<String>> unresolved)
	{
		for (RankedItem candidate : alternatives)
		{
			if (!assumeSlayerTask && isSlayerTaskConditional(candidate))
			{
				continue;
			}
			Optional<ResolvedItem> resolved = resolveCandidate(candidate);
			if (!resolved.isPresent())
			{
				if (unresolved != null)
				{
					unresolved.computeIfAbsent(slot, k -> new ArrayList<>()).add(candidate.getName());
				}
				continue;
			}
			Integer ownedId = firstOwned(resolved.get(), ownedIds);
			return new SlotPick(slot, candidate,
				ownedId != null ? ownedId : resolved.get().getPrimaryId(), ownedId != null, true);
		}
		return null;
	}

	/**
	 * Set pieces (void, blood moon, crystal armour…) are only recommended
	 * because of their set bonus — "always" pieces unconditionally, others
	 * only when the wiki footnote flags the recommendation as full-set. When
	 * the player can't complete the set (or lacks the paired weapon), the
	 * piece is skipped so the next best alternative wins instead.
	 */
	private boolean setSatisfied(RankedItem item, Set<Integer> ownedIds)
	{
		ItemSets.Requirement requirement = ItemSets.requirementFor(item.getName());
		if (requirement == null)
		{
			return true;
		}
		if (!requirement.isAlways() && !ItemSets.setConditionalNote(item.getNote()))
		{
			return true;
		}
		for (ItemSets.PieceGroup group : requirement.getOtherPieces())
		{
			if (!anyOwned(group.getNames(), ownedIds))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * A required group counts as worn when its piece IS the pick for its
	 * slot, or when the piece is owned and its slot isn't claimed by some
	 * other owned pick (the player would naturally fill it with the set
	 * piece — also covers setups that don't list that slot at all).
	 */
	private boolean setWornInLayout(ItemSets.Requirement requirement,
		Map<EquipSlot, SlotPick> pickBySlot, Set<Integer> ownedIds)
	{
		for (ItemSets.PieceGroup group : requirement.getOtherPieces())
		{
			// Owning the weapon is enough. Only one can be worn, but a loadout
			// routinely carries several and swaps between them — Fortis
			// Colosseum lists fang, bow of faerdhinen and sanguinesti staff in
			// one slot — so crystal armour is still right when the bow is a
			// switch that lost the slot to a melee weapon. Armour is not
			// swapped mid-fight, so those groups stay strict: owning blood
			// moon body doesn't justify the helm when Bandos wins the slot.
			if (group.getSlot() == EquipSlot.WEAPON)
			{
				if (!anyOwned(group.getNames(), ownedIds))
				{
					return false;
				}
				continue;
			}

			SlotPick slotPick = pickBySlot.get(group.getSlot());
			if (slotPick != null && slotPick.isOwned())
			{
				if (!anyOwned(group.getNames(), Collections.singleton(slotPick.getItemId())))
				{
					return false;
				}
			}
			else if (!anyOwned(group.getNames(), ownedIds))
			{
				return false;
			}
		}
		return true;
	}

	private boolean anyOwned(List<String> names, Set<Integer> ownedIds)
	{
		for (String name : names)
		{
			Optional<ResolvedItem> resolved = itemResolver.resolve(name);
			if (resolved.isPresent() && firstOwned(resolved.get(), ownedIds) != null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A two-handed weapon pick makes a shield pick contradictory — the wiki
	 * lists shields for the one-handed alternatives. Returns the picks with
	 * the shield removed, or the original list when nothing conflicts.
	 */
	public static List<SlotPick> dropShieldForTwoHanded(List<SlotPick> picks, IntPredicate isTwoHanded)
	{
		boolean twoHanded = false;
		for (SlotPick pick : picks)
		{
			if (pick.getSlot() == EquipSlot.WEAPON && isTwoHanded.test(pick.getItemId()))
			{
				twoHanded = true;
				break;
			}
		}
		if (!twoHanded)
		{
			return picks;
		}
		List<SlotPick> filtered = new ArrayList<>(picks.size());
		for (SlotPick pick : picks)
		{
			if (pick.getSlot() != EquipSlot.SHIELD)
			{
				filtered.add(pick);
			}
		}
		return filtered;
	}

	/**
	 * Owned items from the setup's ranked alternatives that were NOT picked —
	 * switches and spec weapons the player has banked. Wiki-table order,
	 * deduplicated, excluding {@code excludeIds} (the already-placed picks).
	 */
	public List<Integer> ownedAlternatives(GearSetup setup, Set<Integer> ownedIds,
		boolean assumeSlayerTask, Set<Integer> excludeIds)
	{
		List<Integer> extras = new ArrayList<>();
		for (Map.Entry<EquipSlot, List<RankedItem>> entry : setup.getSlots().entrySet())
		{
			for (RankedItem candidate : entry.getValue())
			{
				if (!assumeSlayerTask && isSlayerTaskConditional(candidate))
				{
					continue;
				}
				if (!setSatisfied(candidate, ownedIds))
				{
					continue;
				}
				Optional<ResolvedItem> resolved = resolveCandidate(candidate);
				if (!resolved.isPresent())
				{
					continue;
				}
				Integer ownedId = firstOwned(resolved.get(), ownedIds);
				if (ownedId != null && !excludeIds.contains(ownedId) && !extras.contains(ownedId))
				{
					extras.add(ownedId);
				}
			}
		}
		return extras;
	}

	/**
	 * Wiki footnotes flag items that are only best-in-slot while on a slayer
	 * task (e.g. "If on a Zulrah slayer boss task" on the slayer helmet).
	 * When the user isn't assuming a task, such items are skipped entirely —
	 * they must satisfy neither ownership nor the goal-item fallback.
	 */
	/**
	 * Whether any recommendation in the setup only applies while on a slayer
	 * task — drives whether the panel offers the "on a slayer task" choice at
	 * all, so it appears exactly on the pages where it changes something.
	 */
	public static boolean hasSlayerConditional(GearSetup setup)
	{
		for (List<RankedItem> alternatives : setup.getSlots().values())
		{
			for (RankedItem item : alternatives)
			{
				if (isSlayerTaskConditional(item))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * The task-conditional items and their notes, so the checkbox can show the
	 * wiki's own wording — conditions are monster-specific ("Only on Fossil
	 * Island wyvern task") and "on a slayer task" alone overstates them.
	 * Deduplicated by item name, insertion order preserved.
	 */
	public static List<String> slayerConditionalNotes(GearSetup setup)
	{
		Map<String, String> byItem = new java.util.LinkedHashMap<>();
		for (List<RankedItem> alternatives : setup.getSlots().values())
		{
			for (RankedItem item : alternatives)
			{
				if (isSlayerTaskConditional(item) && item.getNote() != null)
				{
					byItem.putIfAbsent(item.getName(), item.getNote());
				}
			}
		}
		List<String> notes = new ArrayList<>(byItem.size());
		for (Map.Entry<String, String> e : byItem.entrySet())
		{
			notes.add(e.getKey() + " — " + e.getValue());
		}
		return notes;
	}

	/**
	 * Phrasings that mean "only when you're on a task". The footnote form
	 * spells out "Slayer task", but the bare parenthetical the pages use just
	 * as often does not — "(on task)", "(task only)" — so requiring the word
	 * "slayer" missed roughly half of them.
	 */
	private static final String[] TASK_ONLY_PHRASES = {
		"on task", "on a task", "task only", "only on task", "while on task",
	};

	/**
	 * The slayer-effect items a note might name. When a note names one of
	 * these but the item it's attached to isn't it, the task condition belongs
	 * to that other item, not this one.
	 */
	private static final String[] TASK_ITEMS = {
		"slayer helmet", "slayer helm", "black mask", "salve amulet",
	};

	static boolean isSlayerTaskConditional(RankedItem item)
	{
		String note = item.getNote();
		if (note == null)
		{
			return false;
		}
		String n = note.toLowerCase(java.util.Locale.ROOT);
		if (!n.contains("task"))
		{
			return false;
		}

		// The note describes the OFF-task case — gating it would hide the item
		// exactly when it's wanted (Dual macuahuitl on Custodian stalker).
		if (n.contains("off-task") || n.contains("off task"))
		{
			return false;
		}
		// The condition names a DIFFERENT task item than this one, so it
		// belongs to that item ("Downgrade to glory if bringing a Slayer
		// helmet on task" attached to the Amulet of rancour).
		String self = ItemNames.normalize(item.getName());
		for (String taskItem : TASK_ITEMS)
		{
			if (n.contains(taskItem) && !self.contains(taskItem))
			{
				return false;
			}
		}
		// A task phrase with an escape hatch is a preference, not a gate
		// ("If on task, or have 8 ranged strength…" on the Toxic blowpipe).
		if (followedByOr(n))
		{
			return false;
		}

		if (n.contains("slayer"))
		{
			return true;
		}
		for (String phrase : TASK_ONLY_PHRASES)
		{
			if (n.contains(phrase))
			{
				return true;
			}
		}
		return false;
	}

	/** True when a task phrase is followed shortly by " or " — an alternative. */
	private static boolean followedByOr(String note)
	{
		for (String phrase : TASK_ONLY_PHRASES)
		{
			int at = note.indexOf(phrase);
			if (at >= 0 && note.indexOf(" or ", at) >= 0
				&& note.indexOf(" or ", at) - at < 40)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The specific owned variant to place in the layout. acceptableIds
	 * iterates insertion order with the primary (exact-name) id first, so an
	 * owned exact match beats an owned variant.
	 */
	private static Integer firstOwned(ResolvedItem resolved, Set<Integer> ownedIds)
	{
		for (int id : resolved.getAcceptableIds())
		{
			if (ownedIds.contains(id))
			{
				return id;
			}
		}
		return null;
	}
}

package com.wikigearsetups.bank;

import com.wikigearsetups.wiki.EquipSlot;
import com.wikigearsetups.wiki.GearSetup;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * A gear setup resolved against what the player owns. Slots the player has
 * nothing for land in emptySlots (unless config asked for goal items).
 * unresolvedNames holds wiki names the item index couldn't map — surfaced in
 * the preview so failures are never silent.
 */
@Value
public class SetupResolution
{
	GearSetup setup;
	List<SlotPick> picks;
	Map<EquipSlot, List<String>> unresolvedNames;
	List<EquipSlot> emptySlots;
}

package com.wikigearsetups.bank;

import com.wikigearsetups.wiki.EquipSlot;
import com.wikigearsetups.wiki.RankedItem;
import lombok.Value;

/**
 * The outcome for one equipment slot: which recommendation was satisfied and
 * by which specific item id. owned=false means a goal item the player lacks
 * (only produced under MissingGearBehavior.SHOW_BEST_UNOWNED).
 */
@Value
public class SlotPick
{
	EquipSlot slot;
	RankedItem item;
	int itemId;
	boolean owned;
	boolean topRecommendation;
}

package com.wikigearsetups.items;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;

/**
 * Builds a name/id index by scanning every item definition, chunked across
 * client frames to avoid a startup stall. Noted items and placeholders are
 * excluded. Immutable maps are published via volatile fields once complete.
 */
@Slf4j
@Singleton
public class ClientItemNameIndex implements ItemNameIndex
{
	private static final int CHUNK_SIZE = 4000;

	private final Client client;
	private final ClientThread clientThread;

	private volatile Map<String, List<Integer>> byName = Collections.emptyMap();
	private volatile Map<Integer, String> byId = Collections.emptyMap();
	private volatile boolean ready;
	private volatile boolean building;

	@Inject
	public ClientItemNameIndex(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	/** Kicks off the scan if not already built or in progress. Safe to call repeatedly. */
	public void ensureBuilt()
	{
		if (ready || building)
		{
			return;
		}
		building = true;
		long start = System.currentTimeMillis();
		Map<String, List<Integer>> names = new HashMap<>();
		Map<Integer, String> ids = new HashMap<>();
		clientThread.invokeLater(() -> buildChunk(0, names, ids, start));
	}

	private void buildChunk(int from, Map<String, List<Integer>> names, Map<Integer, String> ids, long startMs)
	{
		int count = client.getItemCount();
		int to = Math.min(from + CHUNK_SIZE, count);
		for (int id = from; id < to; id++)
		{
			ItemComposition def = client.getItemDefinition(id);
			if (def == null)
			{
				continue;
			}
			String name = def.getName();
			if (name == null || name.equals("null"))
			{
				continue;
			}
			if (def.getNote() != -1 || def.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			ids.put(id, name);
			names.computeIfAbsent(ItemNames.normalize(name), k -> new ArrayList<>()).add(id);
		}

		if (to < count)
		{
			clientThread.invokeLater(() -> buildChunk(to, names, ids, startMs));
		}
		else
		{
			byName = names;
			byId = ids;
			ready = true;
			building = false;
			log.debug("Item name index built: {} names, {} items in {}ms",
				names.size(), ids.size(), System.currentTimeMillis() - startMs);
		}
	}

	@Override
	public List<Integer> idsByName(String normalizedName)
	{
		List<Integer> ids = byName.get(normalizedName);
		return ids == null ? Collections.emptyList() : ids;
	}

	@Override
	public String nameById(int itemId)
	{
		return byId.get(itemId);
	}

	@Override
	public boolean isReady()
	{
		return ready;
	}
}

package com.wikigearsetups.items;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Interchangeable-consumable classes, best first. When a recommended
 * consumable isn't owned, the best owned member of its class substitutes —
 * an unowned Shark slot becomes your Monkfish rather than a goal item.
 * Groups are keyed by every member (dose-stripped), so "Prayer potion"
 * finds the restore group regardless of how the wiki wrote the dose.
 */
public final class ConsumableGroups
{
	private static final Map<String, List<String>> BY_MEMBER = new HashMap<>();

	static
	{
		group(
			"Anglerfish", "Dark crab", "Manta ray", "Sea turtle", "Shark",
			"Monkfish", "Potato with cheese", "Bass", "Lobster", "Swordfish",
			"Tuna", "Salmon", "Trout", "Cake");
		group("Super restore(4)", "Sanfew serum(4)", "Prayer potion(4)");
	}

	private static void group(String... members)
	{
		List<String> list = Arrays.asList(members);
		for (String member : members)
		{
			BY_MEMBER.put(key(member), list);
		}
	}

	private static String key(String name)
	{
		return ItemNames.stripChargeDecorations(ItemNames.normalize(name));
	}

	private ConsumableGroups()
	{
	}

	/** The item's class, best first, or empty if it isn't a grouped consumable. */
	public static List<String> groupFor(String name)
	{
		List<String> group = BY_MEMBER.get(key(name));
		return group == null ? Collections.emptyList() : group;
	}
}

package com.wikigearsetups.items;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Two kinds of wiki-name knowledge the variation mapping can't express:
 *
 * Generic names — the wiki writes "Imbued god cape" but no item carries that
 * name; any of the concrete god capes satisfies it.
 *
 * Upgrades — distinct items (separate variation groups, often differently
 * named) where owning the better or equivalent one satisfies a
 * recommendation for the lesser: a Divine rune pouch IS a rune pouch, an
 * Uncharged trident IS a trident of the seas. Chains resolve transitively
 * and must stay acyclic.
 */
public final class ItemAliases
{
	private static final Map<String, List<String>> GENERIC = new HashMap<>();
	private static final Map<String, List<String>> UPGRADES = new HashMap<>();
	private static final Map<String, List<String>> EQUIVALENT = new HashMap<>();

	private static final String[] GODS = {
		"Guthix", "Saradomin", "Zamorak", "Ancient", "Armadyl", "Bandos",
	};

	/** Diary rewards exist as tiers 1-4; the wiki writes the bare family name. */
	private static final int DIARY_TIERS = 4;

	static
	{
		// interchangeable within their tier: the wiki names one god cape but
		// any of them does the same job, and pages disagree on which to name
		equivalent("Imbued saradomin cape", "Imbued guthix cape", "Imbued zamorak cape",
			"Imbued saradomin max cape", "Imbued guthix max cape", "Imbued zamorak max cape");
		equivalent("Saradomin cape", "Guthix cape", "Zamorak cape");

		// dye recolours: same item and tier, but the dye names are ordinary
		// words ("Blood", "Ice", "Holy") that can't be stripped generically
		// without colliding with real item families (Blood moon, Ice barrage),
		// so the handful that exist are listed. Ornament kits "(or)" and Echo
		// recolours are handled generically in ItemResolver instead.
		equivalent("Ancient sceptre", "Blood ancient sceptre", "Ice ancient sceptre",
			"Shadow ancient sceptre", "Smoke ancient sceptre");
		equivalent("Scythe of vitur", "Holy scythe of vitur", "Sanguine scythe of vitur");
		equivalent("Torva full helm", "Sanguine torva full helm");
		equivalent("Torva platebody", "Sanguine torva platebody");
		equivalent("Torva platelegs", "Sanguine torva platelegs");

		generic("God cape", "Saradomin cape", "Guthix cape", "Zamorak cape");
		generic("Imbued god cape",
			"Imbued saradomin cape", "Imbued guthix cape", "Imbued zamorak cape",
			"Imbued saradomin max cape", "Imbued guthix max cape", "Imbued zamorak max cape");
		generic("God book",
			"Holy book", "Book of balance", "Unholy book",
			"Book of law", "Book of war", "Book of darkness");

		// God ("blessed") d'hide: the wiki names the set, the game names the
		// god. Every piece is identical in stats, so any of them will do —
		// and pages write the same slot half a dozen different ways.
		godDhide("d'hide body", "Blessed body", "Blessed d'hide body",
			"Blessed dragonhide body", "Blessed dragonhide chestplate");
		godDhide("chaps", "Blessed chaps", "Blessed d'hide chaps",
			"Blessed dragonhide chaps", "Blessed dragonhide legs");
		godDhide("d'hide boots", "Blessed boots", "Blessed d'hide boots",
			"Blessed dragonhide boots");
		godDhide("coif", "Blessed coif", "Blessed d'hide coif", "Blessed dragonhide coif");
		godDhide("bracers", "Blessed bracers", "Blessed vambraces",
			"Blessed d'hide vambraces", "Blessed dragonhide vambraces");
		godDhide("d'hide shield", "Blessed shield", "Blessed d'hide shield",
			"Blessed dragonhide shield");
		godDhide("halo", "Halo");

		generic("Blessing", "Holy blessing", "Unholy blessing", "Peaceful blessing",
			"War blessing", "Honourable blessing", "Ancient blessing");
		// pages write "God blessing" as the family name (Revenants ammo slot)
		generic("God blessing", "Holy blessing", "Unholy blessing", "Peaceful blessing",
			"War blessing", "Honourable blessing", "Ancient blessing");

		// Diary rewards: the wiki names the family, the game numbers the tier.
		// Highest first so the ownership walk lands on the best one held.
		diaryTiers("Ardougne cloak");
		diaryTiers("Explorer's ring");
		diaryTiers("Rada's blessing");
		diaryTiers("Karamja gloves");
		diaryTiers("Desert amulet");
		diaryTiers("Morytania legs");
		diaryTiers("Fremennik sea boots");
		diaryTiers("Falador shield");
		diaryTiers("Varrock armour");

		// Wintertodt asks for "warm clothing" without naming anything. Best
		// first: the torch also lights braziers, so it earns the top spot.
		generic("Warm clothing",
			"Bruma torch", "Warm gloves", "Infernal cape", "Fire cape",
			"Clue hunter garb", "Clue hunter trousers", "Clue hunter gloves",
			"Clue hunter boots", "Clue hunter cloak",
			"Santa hat", "Woolly hat", "Woolly scarf", "Bomber jacket", "Bomber cap",
			"Yak-hide armour (top)", "Yak-hide armour (legs)",
			"Polar camo top", "Polar camo legs");

		upgrade("Rune pouch", "Rune pouch (l)", "Divine rune pouch", "Divine rune pouch (l)");
		upgrade("Divine rune pouch", "Divine rune pouch (l)");
		upgrade("Saradomin cape", "Imbued saradomin cape");
		upgrade("Guthix cape", "Imbued guthix cape");
		upgrade("Zamorak cape", "Imbued zamorak cape");
		upgrade("Toxic blowpipe", "Toxic blowpipe (empty)", "Blazing blowpipe", "Blazing blowpipe (empty)");
		upgrade("Blazing blowpipe", "Blazing blowpipe (empty)");
		// Dizana's quiver outclasses the assemblers
		upgrade("Ava's accumulator", "Ava's assembler");
		upgrade("Ava's assembler",
			"Masori assembler", "Dizana's quiver (uncharged)", "Dizana's quiver",
			"Blessed dizana's quiver", "Dizana's max cape");
		upgrade("Masori assembler", "Masori assembler max cape");
		upgrade("Dizana's quiver", "Blessed dizana's quiver", "Dizana's max cape");
		// charged weapons whose uncharged state carries a different name
		upgrade("Trident of the seas", "Uncharged trident", "Trident of the seas (full)");
		upgrade("Trident of the seas (e)", "Uncharged trident (e)", "Trident of the seas (full) (e)");
		upgrade("Trident of the swamp", "Uncharged toxic trident");
		upgrade("Trident of the swamp (e)", "Uncharged toxic trident (e)");
		upgrade("Toxic staff of the dead", "Toxic staff (uncharged)");
		// the slayer helmet is an assembled black mask
		upgrade("Black mask", "Slayer helmet");
		upgrade("Black mask (i)", "Slayer helmet (i)");
		upgrade("Void knight top", "Elite void top");
		upgrade("Void knight robe", "Elite void robe");
		upgrade("Salve amulet", "Salve amulet (e)", "Salve amulet (i)", "Salve amulet (ei)");
		upgrade("Salve amulet (e)", "Salve amulet (ei)");
		upgrade("Salve amulet (i)", "Salve amulet (ei)");
		// (r)/(i)/(ri) suffixes defeat the startsWith rule — "(ri)" doesn't
		// extend "(i)" textually even though it's the same ring, imbued+recoil
		upgrade("Ring of suffering", "Ring of suffering (r)", "Ring of suffering (i)", "Ring of suffering (ri)");
		upgrade("Ring of suffering (i)", "Ring of suffering (ri)");
		upgrade("Ring of suffering (r)", "Ring of suffering (ri)");
	}

	private static void generic(String name, String... concrete)
	{
		GENERIC.put(ItemNames.normalize(name), Arrays.asList(concrete));
	}

	/**
	 * Registers every way the pages write one god-armour slot against the six
	 * concrete gods' pieces ("Blessed d'hide body" and "Blessed body" both
	 * accept "Guthix d'hide body" and its five siblings).
	 */
	private static void godDhide(String piece, String... wikiNames)
	{
		List<String> concrete = new ArrayList<>(GODS.length);
		for (String god : GODS)
		{
			concrete.add(god + " " + piece);
		}
		for (String wikiName : wikiNames)
		{
			GENERIC.put(ItemNames.normalize(wikiName), concrete);
		}
	}

	private static void diaryTiers(String family)
	{
		List<String> tiers = new ArrayList<>(DIARY_TIERS);
		for (int tier = DIARY_TIERS; tier >= 1; tier--)
		{
			tiers.add(family + " " + tier);
		}
		GENERIC.put(ItemNames.normalize(family), tiers);
	}

	private static void upgrade(String name, String... betterItems)
	{
		UPGRADES.put(ItemNames.normalize(name), Arrays.asList(betterItems));
	}

	/** Registers a mutually interchangeable group: each member accepts the others. */
	private static void equivalent(String... members)
	{
		for (String member : members)
		{
			List<String> others = new ArrayList<>(members.length - 1);
			for (String other : members)
			{
				if (!other.equals(member))
				{
					others.add(other);
				}
			}
			EQUIVALENT.put(ItemNames.normalize(member), others);
		}
	}

	private ItemAliases()
	{
	}

	/** Concrete item names a generic wiki name stands for, or empty. */
	public static List<String> genericFor(String name)
	{
		List<String> concrete = GENERIC.get(ItemNames.normalize(name));
		return concrete == null ? Collections.emptyList() : concrete;
	}

	/** Additional item names that also satisfy a recommendation for {@code name}, or empty. */
	public static List<String> upgradesFor(String normalizedName)
	{
		List<String> upgrades = UPGRADES.get(normalizedName);
		return upgrades == null ? Collections.emptyList() : upgrades;
	}

	/** Same-tier interchangeable items for {@code name}, or empty. */
	public static List<String> equivalentsFor(String normalizedName)
	{
		List<String> equivalents = EQUIVALENT.get(normalizedName);
		return equivalents == null ? Collections.emptyList() : equivalents;
	}
}

package com.wikigearsetups.items;

import java.util.List;
import javax.annotation.Nullable;

/**
 * Bidirectional item name/id lookup. Backed by a scan of client item
 * definitions at runtime; faked in tests.
 */
public interface ItemNameIndex
{
	/** Item ids whose in-game name matches (after {@link ItemNames#normalize}). Empty if none or not ready. */
	List<Integer> idsByName(String normalizedName);

	@Nullable
	String nameById(int itemId);

	boolean isReady();
}

package com.wikigearsetups.items;

import java.util.Locale;

/** Name normalization shared by the index and the resolver. */
public final class ItemNames
{
	private ItemNames()
	{
	}

	/**
	 * Lowercase, straight apostrophes, collapsed whitespace, and no space
	 * before parentheses — the game is inconsistent ("Salve amulet(i)" but
	 * "Ring of suffering (i)") and the wiki always writes the space.
	 *
	 * Underscores become spaces: links are sometimes written in URL form
	 * ("{{plink|Blessed_bracers}}"), and no item name contains one.
	 */
	public static String normalize(String name)
	{
		return name
			.replace('’', '\'')
			.replace('_', ' ')
			.toLowerCase(Locale.ROOT)
			.replaceAll("\\s+\\(", "(")
			.replaceAll("\\s+", " ")
			.trim();
	}

	/**
	 * Removes charge/degradation decorations so variants compare equal to
	 * their base: parenthesized numbers "(10)" and a trailing bare number
	 * ("Karil's leathertop 100"). Non-numeric parens like "(i)" are kept —
	 * they distinguish genuinely different items.
	 */
	public static String stripChargeDecorations(String normalizedName)
	{
		return normalizedName
			.replaceAll("\\(\\d+\\)", "")
			.replaceAll("\\s+\\d+$", "")
			.replaceAll("\\s+", " ")
			.trim();
	}
}

package com.wikigearsetups.items;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Resolves a wiki item name to the set of item ids that satisfy the
 * recommendation.
 *
 * Variation groups (ItemVariationMapping) merge cosmetic recolors, charge
 * states AND upgrade tiers — e.g. plain and imbued black masks share one
 * group. Expansion is therefore filtered by name so a lesser tier never
 * satisfies a higher-tier recommendation:
 *  - equal after stripping charge decorations (charges/degradation), or
 *  - candidate starts with the wiki name (suffixed upgrades, e.g. "(e)"), or
 *  - candidate ends with the wiki name (recolor prefixes, e.g. "Black slayer helmet (i)").
 */
@Singleton
public class ItemResolver
{
	private final ItemNameIndex index;

	@Inject
	public ItemResolver(ItemNameIndex index)
	{
		this.index = index;
	}

	private static final Pattern TRAILING_PAREN = Pattern.compile("\\s*\\([^)]*\\)$");
	private static final Pattern LEADING_QUANTITY = Pattern.compile("^\\d+\\s*[x×]\\s*", Pattern.CASE_INSENSITIVE);
	private static final Pattern TRAILING_QUANTITY = Pattern.compile("\\s*[x×]\\s*\\d+$", Pattern.CASE_INSENSITIVE);
	private static final Pattern TRAILING_NUMBER = Pattern.compile("\\s+\\d+$");

	/**
	 * Purely cosmetic decorations that share a base item's stats and tier. Each
	 * suffix/prefix is unambiguous — it can only denote the decoration, never a
	 * different item — so owning the decorated copy satisfies the base rec:
	 * ornament kit "(or)", gilded "(g)", trimmed "(t)", heraldic "(h1)"-"(h5)",
	 * Deadman "(deadman)", and the Echo recolours ("Echo virtus mask").
	 */
	private static final String[] COSMETIC_SUFFIXES = {
		" (or)", " (g)", " (t)", " (h1)", " (h2)", " (h3)", " (h4)", " (h5)", " (deadman)",
	};
	private static final String[] COSMETIC_PREFIXES = {
		"Echo ",
	};

	/**
	 * Empty when the name is unknown — callers should check
	 * {@code index.isReady()} to distinguish "unknown" from "index not built yet".
	 *
	 * Wiki names diverge from in-game names in recurring ways, each tried in
	 * order until one resolves: quantity markers ("2 x Shark"), potion names
	 * without a dose ("Stamina potion" — the item is "Stamina potion(4)"),
	 * page disambiguators ("Teleport to house (tablet)"), plurals ("Sharks"),
	 * and generic names with no item of their own ("Imbued god cape").
	 */
	public Optional<ResolvedItem> resolve(String wikiName)
	{
		for (String candidate : candidateNames(wikiName))
		{
			Optional<ResolvedItem> resolved = resolveExact(candidate);
			if (!resolved.isPresent())
			{
				resolved = resolveGeneric(candidate);
			}
			if (resolved.isPresent())
			{
				return resolved;
			}
		}
		return Optional.empty();
	}

	private static List<String> candidateNames(String wikiName)
	{
		Set<String> names = new LinkedHashSet<>();
		String raw = wikiName.trim();
		names.add(raw);
		String base = LEADING_QUANTITY.matcher(raw).replaceFirst("");
		base = TRAILING_QUANTITY.matcher(base).replaceFirst("").trim();
		names.add(base);
		if (!base.endsWith(")"))
		{
			names.add(base + "(4)");
		}
		String noParen = TRAILING_PAREN.matcher(base).replaceFirst("");
		if (!noParen.isEmpty())
		{
			names.add(noParen);
		}
		// a bare trailing count with no "x" ("Coins 10000" -> "Coins"). Tried
		// after the exact name, so genuinely numbered items ("Ardougne cloak
		// 4") still resolve as themselves first.
		String noNumber = TRAILING_NUMBER.matcher(base).replaceFirst("");
		if (!noNumber.isEmpty() && !noNumber.equals(base))
		{
			names.add(noNumber);
		}
		// storage sacks are named by their closed form; the wiki writes the
		// open state ("Open herb sack" -> "Herb sack")
		if (base.regionMatches(true, 0, "Open ", 0, 5))
		{
			names.add(base.substring(5));
		}
		if (base.length() > 3 && base.endsWith("s"))
		{
			String singular = base.substring(0, base.length() - 1);
			names.add(singular);
			names.add(singular + "(4)");
		}
		names.remove("");
		return new ArrayList<>(names);
	}

	/** Generic wiki names ("Imbued god cape") accept any of their concrete items. */
	private Optional<ResolvedItem> resolveGeneric(String name)
	{
		List<String> concrete = ItemAliases.genericFor(name);
		if (concrete.isEmpty())
		{
			return Optional.empty();
		}
		Integer primary = null;
		Set<Integer> acceptable = new LinkedHashSet<>();
		for (String c : concrete)
		{
			Optional<ResolvedItem> resolved = resolveExact(c);
			if (resolved.isPresent())
			{
				if (primary == null)
				{
					primary = resolved.get().getPrimaryId();
				}
				acceptable.addAll(resolved.get().getAcceptableIds());
			}
		}
		return primary == null
			? Optional.empty()
			: Optional.of(new ResolvedItem(name, primary, acceptable));
	}

	private Optional<ResolvedItem> resolveExact(String wikiName)
	{
		String wiki = ItemNames.normalize(wikiName);
		List<Integer> primary = index.idsByName(wiki);
		if (primary.isEmpty())
		{
			return Optional.empty();
		}

		Set<Integer> acceptable = new LinkedHashSet<>(primary);
		String wikiStripped = ItemNames.stripChargeDecorations(wiki);

		for (int id : primary)
		{
			for (int variant : ItemVariationMapping.getVariations(ItemVariationMapping.map(id)))
			{
				String name = index.nameById(variant);
				if (name == null)
				{
					continue;
				}
				String candidate = ItemNames.normalize(name);
				if (ItemNames.stripChargeDecorations(candidate).equals(wikiStripped)
					|| candidate.startsWith(wiki)
					|| candidate.endsWith(wiki))
				{
					acceptable.add(variant);
				}
			}
		}

		// trouver-locked "(l)" variants aren't always in the variation group
		acceptable.addAll(index.idsByName(ItemNames.normalize(wiki + " (l)")));

		// cosmetic variants are the same item at the same tier, so an owned
		// decorated copy satisfies a recommendation for the base. They aren't
		// reliably grouped by ItemVariationMapping, so accept them by name.
		// Every marker here is unambiguous — it can only mean the decoration —
		// so none can cross into a different item. Overloaded dye prefixes
		// ("Blood", "Ice") are handled per-item in ItemAliases instead.
		for (String suffix : COSMETIC_SUFFIXES)
		{
			acceptable.addAll(index.idsByName(ItemNames.normalize(wiki + suffix)));
		}
		for (String prefix : COSMETIC_PREFIXES)
		{
			acceptable.addAll(index.idsByName(ItemNames.normalize(prefix + wiki)));
		}

		// distinct upgrade items in other variation groups (Divine rune pouch
		// for "Rune pouch") also satisfy the recommendation
		for (String upgrade : ItemAliases.upgradesFor(wiki))
		{
			resolveExact(upgrade).ifPresent(r -> acceptable.addAll(r.getAcceptableIds()));
		}

		// same-tier interchangeables (the three imbued god capes). Looked up
		// by name rather than resolved, since the relation is bidirectional
		// and resolving would recurse forever
		for (String equivalent : ItemAliases.equivalentsFor(wiki))
		{
			acceptable.addAll(index.idsByName(ItemNames.normalize(equivalent)));
		}

		// a divine potion satisfies its base potion (never the reverse)
		if (wiki.contains("potion") && !wiki.startsWith("divine "))
		{
			resolveExact("divine " + wiki).ifPresent(r -> acceptable.addAll(r.getAcceptableIds()));
		}

		return Optional.of(new ResolvedItem(wikiName, primary.get(0), acceptable));
	}
}

package com.wikigearsetups.items;

import com.wikigearsetups.wiki.EquipSlot;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Items whose recommendation is only valid as part of a set (or alongside a
 * specific weapon). Two gating modes:
 *
 * always — the piece is pointless without its set (void; crystal armour
 * without a crystal bow), so the requirement applies to every
 * recommendation of it.
 *
 * note-flagged — the piece is reasonable standalone gear (barrows, moon
 * sets, obsidian, justiciar) and is gated only when the wiki footnote on
 * that particular recommendation says "full/complete ... set". The same
 * item can appear both gated (rank 2, with note) and ungated (rank 3,
 * standalone) on one page — Amoxliatl's Dual macuahuitl does exactly this.
 *
 * Each required group carries the equipment slot it occupies so the
 * resolver can distinguish "worn in this layout" from merely "banked".
 */
public final class ItemSets
{
	/** One required slot of a set: any of these names, worn in {@code slot}. */
	public static final class PieceGroup
	{
		private final EquipSlot slot;
		private final List<String> names;

		private PieceGroup(EquipSlot slot, List<String> names)
		{
			this.slot = slot;
			this.names = names;
		}

		public EquipSlot getSlot()
		{
			return slot;
		}

		public List<String> getNames()
		{
			return names;
		}
	}

	public static final class Requirement
	{
		private final boolean always;
		private final List<PieceGroup> otherPieces;

		private Requirement(boolean always, List<PieceGroup> otherPieces)
		{
			this.always = always;
			this.otherPieces = otherPieces;
		}

		public boolean isAlways()
		{
			return always;
		}

		/** All groups must be satisfied for the piece to be worth wearing. */
		public List<PieceGroup> getOtherPieces()
		{
			return otherPieces;
		}
	}

	private static final Map<String, Requirement> BY_PIECE = new HashMap<>();

	static
	{
		armourSet(true,
			group(EquipSlot.HEAD, "Void melee helm", "Void ranger helm", "Void mage helm"),
			group(EquipSlot.BODY, "Void knight top", "Elite void top"),
			group(EquipSlot.LEGS, "Void knight robe", "Elite void robe"),
			group(EquipSlot.HANDS, "Void knight gloves"));

		// crystal armour only shines behind a crystal bow — per-piece, no set needed
		PieceGroup crystalBows = group(EquipSlot.WEAPON,
			"Bow of faerdhinen", "Bow of faerdhinen (c)", "Bow of faerdhinen (inactive)", "Crystal bow");
		for (String piece : new String[]{"Crystal helm", "Crystal body", "Crystal legs"})
		{
			BY_PIECE.put(ItemNames.normalize(piece),
				new Requirement(true, Collections.singletonList(crystalBows)));
		}

		armourSet(false,
			group(EquipSlot.HEAD, "Justiciar faceguard"),
			group(EquipSlot.BODY, "Justiciar chestguard"),
			group(EquipSlot.LEGS, "Justiciar legguards"));
		armourSet(false,
			group(EquipSlot.HEAD, "Obsidian helmet"),
			group(EquipSlot.BODY, "Obsidian platebody"),
			group(EquipSlot.LEGS, "Obsidian platelegs"));

		barrows("Ahrim's hood", "Ahrim's robetop", "Ahrim's robeskirt", "Ahrim's staff");
		barrows("Dharok's helm", "Dharok's platebody", "Dharok's platelegs", "Dharok's greataxe");
		barrows("Guthan's helm", "Guthan's platebody", "Guthan's chainskirt", "Guthan's warspear");
		barrows("Karil's coif", "Karil's leathertop", "Karil's leatherskirt", "Karil's crossbow");
		barrows("Torag's helm", "Torag's platebody", "Torag's platelegs", "Torag's hammers");
		barrows("Verac's helm", "Verac's brassard", "Verac's plateskirt", "Verac's flail");

		moonSet("Blood moon helm", "Blood moon chestplate", "Blood moon tassets", "Dual macuahuitl");
		moonSet("Blue moon helm", "Blue moon chestplate", "Blue moon tassets", "Blue moon spear");
		moonSet("Eclipse moon helm", "Eclipse moon chestplate", "Eclipse moon tassets", "Eclipse atlatl");
	}

	private static PieceGroup group(EquipSlot slot, String... names)
	{
		return new PieceGroup(slot, Arrays.asList(names));
	}

	private static void barrows(String helm, String body, String legs, String weapon)
	{
		armourSet(false,
			group(EquipSlot.HEAD, helm),
			group(EquipSlot.BODY, body),
			group(EquipSlot.LEGS, legs),
			group(EquipSlot.WEAPON, weapon));
	}

	private static void moonSet(String helm, String chest, String legs, String weapon)
	{
		armourSet(false,
			group(EquipSlot.HEAD, helm),
			group(EquipSlot.BODY, chest),
			group(EquipSlot.LEGS, legs),
			group(EquipSlot.WEAPON, weapon));
	}

	/** Registers each member of each group with a requirement of all OTHER groups. */
	private static void armourSet(boolean always, PieceGroup... pieceGroups)
	{
		for (int i = 0; i < pieceGroups.length; i++)
		{
			List<PieceGroup> others = new ArrayList<>();
			for (int j = 0; j < pieceGroups.length; j++)
			{
				if (j != i)
				{
					others.add(pieceGroups[j]);
				}
			}
			Requirement requirement = new Requirement(always, others);
			for (String piece : pieceGroups[i].getNames())
			{
				BY_PIECE.put(ItemNames.normalize(piece), requirement);
			}
		}
	}

	private ItemSets()
	{
	}

	/** The set requirement covering this item, or null if it isn't a set piece. */
	public static Requirement requirementFor(String name)
	{
		return BY_PIECE.get(ItemNames.normalize(name));
	}

	/** True when a wiki footnote marks the recommendation as full-set-only. */
	public static boolean setConditionalNote(String note)
	{
		if (note == null)
		{
			return false;
		}
		String n = note.toLowerCase(Locale.ROOT);
		return n.contains("set") && (n.contains("full") || n.contains("complete"));
	}
}

package com.wikigearsetups.items;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * The wiki fills some inventory slots with placeholder templates instead of
 * concrete items ({{Cheap food}}, {{Cheap prayer}}). Each maps to concrete
 * candidates, best-owned-first semantics applied by the resolver — so a
 * "Cheap food" slot becomes whichever of these the player actually banks.
 */
public final class PlaceholderItems
{
	private static final Map<String, List<String>> CANDIDATES = new HashMap<>();

	static
	{
		CANDIDATES.put("cheap food", Arrays.asList(
			"Shark", "Monkfish", "Lobster", "Swordfish", "Tuna", "Trout", "Cake"));
		CANDIDATES.put("high healing food", Arrays.asList(
			"Anglerfish", "Manta ray", "Dark crab", "Shark"));
		CANDIDATES.put("cheap prayer", Arrays.asList(
			"Prayer potion(4)", "Super restore(4)"));
		CANDIDATES.put("combo food", Arrays.asList(
			"Cooked karambwan", "Potato with cheese"));
	}

	private PlaceholderItems()
	{
	}

	/**
	 * Joins candidates a choice template listed for itself. Mirrors
	 * {@code InventoryParser.CHOICE_SEPARATOR} — kept here as a literal so the
	 * items package doesn't depend on the wiki package.
	 */
	private static final String CHOICE_SEPARATOR = " / ";

	/**
	 * Concrete candidates for a placeholder name, or empty if not a
	 * placeholder at all.
	 *
	 * Two sources: the table above, for templates that name a class of item
	 * without listing it ({{Cheap food}}), and the slot value itself, for
	 * templates that carry their own list ({{MinPrice|Manta ray|Tuna
	 * potato|…}}) and are joined by the parser.
	 */
	public static List<String> candidatesFor(String name)
	{
		List<String> candidates = CANDIDATES.get(ItemNames.normalize(name));
		if (candidates != null)
		{
			return candidates;
		}
		return name.contains(CHOICE_SEPARATOR)
			? Arrays.asList(name.split(Pattern.quote(CHOICE_SEPARATOR)))
			: Collections.emptyList();
	}
}

