package com.wikigearsetups.layout;

import com.wikigearsetups.WikiGearSetupsConfig;
import com.wikigearsetups.bank.InventoryPick;
import com.wikigearsetups.bank.InventoryResolution;
import com.wikigearsetups.bank.SetupResolution;
import com.wikigearsetups.bank.SlotPick;
import com.wikigearsetups.wiki.EquipSlot;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.plugins.banktags.tabs.TabManager;
import net.runelite.client.plugins.banktags.tabs.TagTab;
import net.runelite.client.util.Text;

/**
 * Writes resolved setups into core Bank Tags: tags each picked item, saves
 * the layout, and creates (or updates) the tag tab. Multiple gear setups
 * import as one tab with a layout block per style.
 *
 * Must run on the client thread. Re-importing the same tag name overwrites:
 * the old tag is cleared first so removed items don't linger.
 *
 * Refuses to run while the Bank Tags plugin is disabled — TabManager's
 * in-memory tab list is only loaded by an enabled Bank Tags plugin, and
 * calling save() against an unloaded list would wipe the user's real tabs.
 */
@Slf4j
@Singleton
public class BankTagImporter
{
	static final int DEFAULT_ICON_ITEM_ID = 952; // spade

	/** Newline-separated tag names this plugin has written, per profile. */
	static final String IMPORTED_TAGS_KEY = "importedTags";

	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final TabManager tabManager;
	private final PluginManager pluginManager;
	private final ConfigManager configManager;

	@Inject
	public BankTagImporter(TagManager tagManager, LayoutManager layoutManager,
		TabManager tabManager, PluginManager pluginManager, ConfigManager configManager)
	{
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.tabManager = tabManager;
		this.pluginManager = pluginManager;
		this.configManager = configManager;
	}

	public boolean isBankTagsEnabled()
	{
		return pluginManager.getPlugins().stream()
			.filter(p -> p instanceof BankTagsPlugin)
			.findFirst()
			.map(pluginManager::isPluginEnabled)
			.orElse(false);
	}

	/** What is already sitting under a tag name, so the user can be asked first. */
	public enum Existing
	{
		/** Nothing — importing creates something new. */
		NONE,
		/** A tab this plugin wrote before; re-importing is the normal refresh path. */
		OURS,
		/** A tab or layout the plugin didn't create — almost certainly hand-made. */
		FOREIGN,
	}

	/**
	 * Whether importing under {@code tag} would replace something, and whose
	 * it is. Client thread only — reads the Bank Tags in-memory state.
	 *
	 * Ownership is tracked rather than inferred: a tag we have imported before
	 * is recorded in config, so anything else that exists is the player's.
	 */
	public Existing existing(String tag)
	{
		boolean present = tabManager.find(tag) != null || layoutManager.loadLayout(tag) != null;
		if (!present)
		{
			return Existing.NONE;
		}
		return importedTags().contains(tag) ? Existing.OURS : Existing.FOREIGN;
	}

	/**
	 * Whether this plugin created the tab under {@code tag}. Standardized on
	 * both sides because core hands back the tag as the player sees it.
	 */
	public boolean wasImported(String tag)
	{
		if (tag == null || tag.isEmpty())
		{
			return false;
		}
		String wanted = Text.standardize(tag);
		for (String imported : importedTags())
		{
			if (wanted.equals(Text.standardize(imported)))
			{
				return true;
			}
		}
		return false;
	}

	private Set<String> importedTags()
	{
		String stored = configManager.getConfiguration(WikiGearSetupsConfig.GROUP, IMPORTED_TAGS_KEY);
		if (stored == null || stored.isEmpty())
		{
			return new LinkedHashSet<>();
		}
		return new LinkedHashSet<>(Arrays.asList(stored.split("\n")));
	}

	private void rememberImported(String tag)
	{
		Set<String> tags = importedTags();
		if (tags.add(tag))
		{
			configManager.setConfiguration(WikiGearSetupsConfig.GROUP, IMPORTED_TAGS_KEY,
				String.join("\n", tags));
		}
	}

	/** Single-setup convenience. */
	public void importSetup(String tag, SetupResolution resolution, LayoutStyle layoutStyle)
	{
		importSetups(tag, Collections.singletonList(resolution), null,
			Collections.emptyList(), layoutStyle, null);
	}

	/** Convenience without extras. */
	public void importSetups(String tag, List<SetupResolution> resolutions,
		@Nullable InventoryResolution inventory, LayoutStyle layoutStyle, @Nullable Integer iconItemId)
	{
		importSetups(tag, resolutions, inventory, Collections.emptyList(), layoutStyle, iconItemId);
	}

	/**
	 * Imports the setups (and optional inventory) as bank tag {@code tag};
	 * {@code extraItemIds} (owned alternates) land below the layout. Client
	 * thread only.
	 */
	public void importSetups(String tag, List<SetupResolution> resolutions,
		@Nullable InventoryResolution inventory, List<Integer> extraItemIds,
		LayoutStyle layoutStyle, @Nullable Integer iconItemId)
	{
		if (!isBankTagsEnabled())
		{
			throw new IllegalStateException("The Bank Tags plugin must be enabled to import a setup");
		}

		Set<Integer> itemIds = new LinkedHashSet<>();
		List<List<SlotPick>> gearBlocks = new ArrayList<>();
		for (SetupResolution resolution : resolutions)
		{
			gearBlocks.add(resolution.getPicks());
			for (SlotPick pick : resolution.getPicks())
			{
				itemIds.add(pick.getItemId());
			}
		}
		List<InventoryPick> inventoryPicks = inventory == null
			? Collections.emptyList()
			: inventory.getPicks();
		List<InventoryPick> runePicks = inventory == null
			? Collections.emptyList()
			: inventory.getRunePicks();
		for (InventoryPick pick : inventoryPicks)
		{
			itemIds.add(pick.getItemId());
		}
		for (InventoryPick pick : runePicks)
		{
			itemIds.add(pick.getItemId());
		}
		itemIds.addAll(extraItemIds);

		if (itemIds.isEmpty())
		{
			throw new IllegalArgumentException("Nothing to import: no items resolved for this setup");
		}

		// overwrite semantics: clear any previous import under this name
		tagManager.removeTag(tag);
		for (int itemId : itemIds)
		{
			tagManager.addTag(itemId, tag, false);
		}

		Layout layout = LayoutBuilder.build(tag, gearBlocks, inventoryPicks, runePicks, extraItemIds, layoutStyle);
		layoutManager.saveLayout(layout);

		int icon = iconItemId != null ? iconItemId : iconFor(resolutions);
		TagTab existing = tabManager.find(tag);
		if (existing == null)
		{
			TagTab tab = new TagTab();
			tab.setTag(tag);
			tab.setIconItemId(icon);
			tabManager.add(tab);
		}
		else
		{
			existing.setIconItemId(icon);
		}
		tabManager.save();
		rememberImported(tag);

		log.debug("Imported bank tag '{}': {} items ({} gear blocks, {} inventory slots)",
			tag, itemIds.size(), gearBlocks.size(), inventoryPicks.size());
	}

	/** Tab icon: the first picked weapon across setups, else the first pick. */
	public static int iconFor(List<SetupResolution> resolutions)
	{
		for (SetupResolution resolution : resolutions)
		{
			for (SlotPick pick : resolution.getPicks())
			{
				if (pick.getSlot() == EquipSlot.WEAPON)
				{
					return pick.getItemId();
				}
			}
		}
		for (SetupResolution resolution : resolutions)
		{
			if (!resolution.getPicks().isEmpty())
			{
				return resolution.getPicks().get(0).getItemId();
			}
		}
		return DEFAULT_ICON_ITEM_ID;
	}
}

package com.wikigearsetups.layout;

import com.wikigearsetups.bank.InventoryPick;
import com.wikigearsetups.bank.SlotPick;
import com.wikigearsetups.wiki.EquipSlot;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.plugins.banktags.tabs.Layout;

/**
 * Produces the bank tag Layout for one or more resolved gear setups plus an
 * optional inventory. Deterministic so re-imports never shuffle positions.
 *
 * EQUIPMENT_SCREEN mirrors the worn-equipment interface in columns 0-3
 * (head; cape/neck/ammo; weapon/body/shield/special; legs; hands/feet/ring),
 * one 5-row block per gear setup stacked vertically — multi-style content
 * (ToA/CoX/ToB) imports as one tab with a block per style. The inventory's
 * 28 wiki slots map onto columns 4-7, rows 0-6, preserving wiki order.
 *
 * An item appearing in several gear blocks is placed only once (you bring
 * one pair of boots); an inventory item already placed as gear is skipped
 * (it's the same switch). Duplicates WITHIN the inventory are kept — the
 * wiki uses repeated slots (karambwans, food) deliberately.
 *
 * COMPACT packs gear blocks as rows separated by a blank row, inventory last.
 */
public final class LayoutBuilder
{
	private static final int BANK_WIDTH = 8;
	private static final int ROWS_PER_BLOCK = 5;
	private static final int INVENTORY_COL = 4;

	/**
	 * Rough height of an all-styles layout in the equipment-screen style: one
	 * five-row block per gear setup. Used to warn before importing a tall tab;
	 * inventory and extras can add a few more rows, hence "about".
	 */
	public static int estimatedRows(int gearBlockCount)
	{
		return gearBlockCount * ROWS_PER_BLOCK;
	}

	private static final Map<EquipSlot, Integer> EQUIPMENT_SCREEN_POS = new EnumMap<>(EquipSlot.class);

	static
	{
		EQUIPMENT_SCREEN_POS.put(EquipSlot.HEAD, 1);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.CAPE, BANK_WIDTH);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.NECK, BANK_WIDTH + 1);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.AMMO, BANK_WIDTH + 2);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.WEAPON, 2 * BANK_WIDTH);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.BODY, 2 * BANK_WIDTH + 1);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.SHIELD, 2 * BANK_WIDTH + 2);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.SPECIAL, 2 * BANK_WIDTH + 3);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.LEGS, 3 * BANK_WIDTH + 1);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.HANDS, 4 * BANK_WIDTH);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.FEET, 4 * BANK_WIDTH + 1);
		EQUIPMENT_SCREEN_POS.put(EquipSlot.RING, 4 * BANK_WIDTH + 2);
	}

	private LayoutBuilder()
	{
	}

	/** Single-setup convenience. */
	public static Layout build(String tag, List<SlotPick> picks, LayoutStyle style)
	{
		return build(tag, Collections.singletonList(picks), Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), style);
	}

	/** Convenience without extras. */
	public static Layout build(String tag, List<List<SlotPick>> gearBlocks,
		List<InventoryPick> inventory, List<InventoryPick> runes, LayoutStyle style)
	{
		return build(tag, gearBlocks, inventory, runes, Collections.emptyList(), style);
	}

	public static Layout build(String tag, List<List<SlotPick>> gearBlocks,
		List<InventoryPick> inventory, List<InventoryPick> runes,
		List<Integer> extras, LayoutStyle style)
	{
		Layout layout = new Layout(tag);
		Set<Integer> placed = new HashSet<>();

		if (style == LayoutStyle.EQUIPMENT_SCREEN)
		{
			int blockRow = 0;
			for (List<SlotPick> block : gearBlocks)
			{
				for (SlotPick pick : sorted(block))
				{
					if (placed.add(pick.getItemId()))
					{
						layout.setItemAtPos(pick.getItemId(),
							blockRow * BANK_WIDTH + EQUIPMENT_SCREEN_POS.get(pick.getSlot()));
					}
				}
				blockRow += ROWS_PER_BLOCK;
			}
			// runes sit directly under the last equipment block, left side
			boolean runesPlaced = false;
			for (InventoryPick rune : runes)
			{
				if (placed.add(rune.getItemId()))
				{
					layout.setItemAtPos(rune.getItemId(), blockRow * BANK_WIDTH + rune.getSlot());
					runesPlaced = true;
				}
			}
			int inventoryRows = 0;
			Set<Integer> inventoryIds = new HashSet<>();
			for (InventoryPick pick : inventory)
			{
				if (!placed.contains(pick.getItemId()))
				{
					int row = pick.getSlot() / 4;
					int col = pick.getSlot() % 4;
					layout.setItemAtPos(pick.getItemId(), row * BANK_WIDTH + INVENTORY_COL + col);
					inventoryIds.add(pick.getItemId());
					inventoryRows = Math.max(inventoryRows, row + 1);
				}
			}
			placed.addAll(inventoryIds);
			// extras (owned alternates) flow below everything, after a blank row
			int extrasRow = Math.max(blockRow + (runesPlaced ? 1 : 0), inventoryRows) + 1;
			int pos = extrasRow * BANK_WIDTH;
			for (int extra : extras)
			{
				if (placed.add(extra))
				{
					layout.setItemAtPos(extra, pos++);
				}
			}
		}
		else
		{
			int pos = 0;
			for (List<SlotPick> block : gearBlocks)
			{
				int placedInBlock = 0;
				for (SlotPick pick : sorted(block))
				{
					if (placed.add(pick.getItemId()))
					{
						layout.setItemAtPos(pick.getItemId(), pos++);
						placedInBlock++;
					}
				}
				if (placedInBlock > 0)
				{
					pos = ((pos + BANK_WIDTH - 1) / BANK_WIDTH + 1) * BANK_WIDTH; // next row + blank row
				}
			}
			for (InventoryPick pick : inventory)
			{
				if (!placed.contains(pick.getItemId()))
				{
					layout.setItemAtPos(pick.getItemId(), pos++);
				}
			}
			for (InventoryPick rune : runes)
			{
				if (placed.add(rune.getItemId()))
				{
					layout.setItemAtPos(rune.getItemId(), pos++);
				}
			}
			if (!extras.isEmpty() && pos > 0)
			{
				pos = ((pos + BANK_WIDTH - 1) / BANK_WIDTH + 1) * BANK_WIDTH;
			}
			for (int extra : extras)
			{
				if (placed.add(extra))
				{
					layout.setItemAtPos(extra, pos++);
				}
			}
		}
		return layout;
	}

	private static List<SlotPick> sorted(List<SlotPick> picks)
	{
		List<SlotPick> ordered = new ArrayList<>(picks);
		ordered.sort(Comparator.comparingInt(p -> p.getSlot().ordinal()));
		return ordered;
	}
}

package com.wikigearsetups.layout;

import com.wikigearsetups.WikiGearSetupsConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.tabs.Layout;

/**
 * Shrinks the bank's scroll range to the end of an imported layout.
 *
 * Core Bank Tags draws an empty slot into every remaining widget child of the
 * bank item container so items can be dragged anywhere ("Fill the remaining
 * slots with -1" in LayoutManager#layout). Those children are allocated per
 * item in the whole bank, so a player with a large bank scrolls through a
 * hundred-odd empty rows below a twelve-row layout. Core only ever clamps the
 * scroll *position* (LayoutManager#scrollLayout), never the range.
 *
 * Setting the range to the last populated row leaves the empty slots on screen
 * and draggable — a tall bank window still shows them under the layout — but
 * stops the scrollbar running off into nothing.
 *
 * Deliberately scoped to tabs this plugin created: a hand-made tab, or one
 * belonging to another plugin, keeps whatever behaviour its owner intended.
 */
@Slf4j
@Singleton
public class LayoutScrollTrimmer
{
	private static final int ROW_HEIGHT =
		BankTagsPlugin.BANK_ITEM_HEIGHT + BankTagsPlugin.BANK_ITEM_Y_PADDING;

	/** Breathing room under the last row, matching what Bank Tag Layouts leaves. */
	private static final int BOTTOM_PADDING = 8;

	private final Client client;
	private final ClientThread clientThread;
	private final BankTagsService bankTagsService;
	private final BankTagImporter importer;
	private final WikiGearSetupsConfig config;

	@Inject
	public LayoutScrollTrimmer(Client client, ClientThread clientThread,
		BankTagsService bankTagsService, BankTagImporter importer, WikiGearSetupsConfig config)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.bankTagsService = bankTagsService;
		this.importer = importer;
		this.config = config;
	}

	/**
	 * Call once the bank has finished building. Client thread only — reads and
	 * writes bank widgets.
	 */
	public void onBankBuilt()
	{
		if (!config.trimEmptySpace())
		{
			return;
		}

		Layout layout = bankTagsService.getActiveLayout();
		if (layout == null || !importer.wasImported(bankTagsService.getActiveTag()))
		{
			return;
		}

		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null)
		{
			return;
		}

		int lastRow = lastUsedRow(layout);
		if (lastRow < 0)
		{
			return;
		}

		int height = (lastRow + 1) * ROW_HEIGHT + BOTTOM_PADDING;
		// only ever shrink: growing the range would invent space the bank has no widgets for
		if (height >= items.getScrollHeight())
		{
			return;
		}

		items.setScrollHeight(height);
		int scrollY = Math.min(items.getScrollY(), Math.max(0, height - items.getHeight()));

		// the script vm isn't reentrant, so the scrollbar refresh has to wait a tick
		clientThread.invokeLater(() -> client.runScript(ScriptID.UPDATE_SCROLLBAR,
			InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scrollY));

		log.debug("Trimmed bank scroll to {}px ({} rows) for '{}'",
			height, lastRow + 1, bankTagsService.getActiveTag());
	}

	/** Row index of the last populated slot, or -1 when the layout is empty. */
	static int lastUsedRow(Layout layout)
	{
		for (int pos = layout.size() - 1; pos >= 0; pos--)
		{
			if (layout.getItemAtPos(pos) > -1)
			{
				return pos / BankTagsPlugin.BANK_ITEMS_PER_ROW;
			}
		}
		return -1;
	}
}

package com.wikigearsetups.layout;

public enum LayoutStyle
{
	EQUIPMENT_SCREEN("Equipment screen"),
	COMPACT("Compact rows");

	private final String label;

	LayoutStyle(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.wikigearsetups.layout;

import java.util.Locale;

/** Builds deterministic bank tag names from wiki page + setup style. */
public final class TagNames
{
	private static final int MAX_LENGTH = 50;

	private TagNames()
	{
	}

	/**
	 * e.g. ("Zulrah/Strategies", "Magic (Diary kill)") -> "zulrah-magic-diary-kill".
	 * Deterministic so re-imports target the same tag.
	 */
	public static String build(String pageTitle, String styleLabel)
	{
		String page = pageTitle;
		int slash = page.indexOf('/');
		if (slash > 0)
		{
			page = page.substring(0, slash);
		}
		String name = slugify(page) + "-" + slugify(styleLabel);
		if (name.length() > MAX_LENGTH)
		{
			name = name.substring(0, MAX_LENGTH);
		}
		return trimDashes(name);
	}

	/** Sanitizes a user-supplied tag name to the same slug rules. */
	public static String sanitize(String s)
	{
		if (s == null)
		{
			return "";
		}
		String name = slugify(s);
		return name.length() > MAX_LENGTH ? trimDashes(name.substring(0, MAX_LENGTH)) : name;
	}

	/**
	 * Prepends {@code prefix} to {@code tag} as one slug. An empty prefix (or
	 * empty tag) is returned unchanged, so the default of no prefix is a no-op.
	 */
	public static String withPrefix(String prefix, String tag)
	{
		String p = sanitize(prefix);
		return p.isEmpty() || tag.isEmpty() ? tag : sanitize(p + "-" + tag);
	}

	private static String slugify(String s)
	{
		return trimDashes(s
			.toLowerCase(Locale.ROOT)
			.replace("'", "")
			.replace('’', '�')
			.replaceAll("[^a-z0-9]+", "-"));
	}

	private static String trimDashes(String s)
	{
		return s.replaceAll("^-+|-+$", "");
	}
}

package com.wikigearsetups.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;
import javax.swing.JCheckBox;
import net.runelite.client.ui.ColorScheme;

/**
 * Checkbox box-and-tick drawn explicitly: the stock dark-on-dark tick is
 * easy to miss, and this toggle changes what Import writes, so its state
 * has to read at a glance.
 */
class CheckBoxIcon implements Icon
{
	private static final int SIZE = 14;

	private final boolean checked;

	private CheckBoxIcon(boolean checked)
	{
		this.checked = checked;
	}

	static void apply(JCheckBox box)
	{
		box.setIcon(new CheckBoxIcon(false));
		box.setSelectedIcon(new CheckBoxIcon(true));
		box.setIconTextGap(6);
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g2.setColor(checked ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
		g2.fillRoundRect(x, y, SIZE, SIZE, 4, 4);
		g2.setColor(checked ? Color.WHITE : ColorScheme.DARKER_GRAY_HOVER_COLOR);
		g2.drawRoundRect(x, y, SIZE, SIZE, 4, 4);

		if (checked)
		{
			g2.setColor(Color.WHITE);
			g2.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g2.drawLine(x + 3, y + 7, x + 6, y + 10);
			g2.drawLine(x + 6, y + 10, x + 11, y + 4);
		}
		g2.dispose();
	}

	@Override
	public int getIconWidth()
	{
		return SIZE;
	}

	@Override
	public int getIconHeight()
	{
		return SIZE;
	}
}

package com.wikigearsetups.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Shown in place of the search UI once per session, and on demand from the
 * footer. In-panel rather than a startup dialog so it can never interrupt
 * play.
 *
 * Everything sits in one scrolling column — logo, title, body, accept,
 * personal note — so the button follows the text instead of being stranded
 * at the bottom of a tall sidebar. Wrapped paragraphs re-render at the
 * panel's real width whenever it changes, since a hard-coded pixel width
 * is what clipped them before.
 */
class DisclaimerPanel extends JPanel
{
	private static final Color HEADING = ColorScheme.BRAND_ORANGE;
	/** RuneLite reserves 17px for the sidebar scrollbar; leave clearance for it. */
	private static final int SIDE_PADDING = 24;

	private final List<Paragraph> paragraphs = new ArrayList<>();
	private final JPanel content;
	private int renderedWidth = -1;

	private static final class Paragraph
	{
		final JLabel label;
		final String text;

		Paragraph(JLabel label, String text)
		{
			this.label = label;
			this.text = text;
		}
	}

	DisclaimerPanel(Icon banner, String version, Runnable onAccept)
	{
		super(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		if (banner != null)
		{
			JLabel bannerLabel = new JLabel(banner);
			bannerLabel.setAlignmentX(LEFT_ALIGNMENT);
			content.add(bannerLabel);
			content.add(Box.createVerticalStrut(14));
		}

		JLabel title = new JLabel("Before you start");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		content.add(title);
		content.add(Box.createVerticalStrut(10));

		addSection(content, "Suspected BIS, not gospel",
			"Recommended items are only suspected best-in-slot. Always do your own research "
				+ "for your account and the content you're doing.");
		addSection(content, "Give each setup a once-over",
			"Wiki pages list several options per slot, so now and then a layout includes "
				+ "something that doesn't quite fit the rest of it — an off-hand next to a "
				+ "two-handed weapon, say.");
		addSection(content, "Found a bug?",
			"Please report any bugs you find to the Git.");

		content.add(Box.createVerticalStrut(6));

		JButton accept = RoundedButton.accent("Got it");
		accept.setFont(accept.getFont().deriveFont(Font.BOLD));
		accept.setAlignmentX(LEFT_ALIGNMENT);
		accept.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		accept.addActionListener(e -> onAccept.run());
		content.add(accept);
		content.add(Box.createVerticalStrut(14));

		JLabel note = paragraph(content,
			"I hope this makes gearing up a little easier. Good luck out there :)");
		note.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		content.add(Box.createVerticalStrut(4));
		JLabel signature = new JLabel("~ Jiimbones");
		signature.setFont(FontManager.getRunescapeFont());
		signature.setForeground(HEADING);
		signature.setAlignmentX(LEFT_ALIGNMENT);
		content.add(signature);

		// build stamp: the first thing worth knowing about a bug report
		content.add(Box.createVerticalStrut(8));
		JLabel build = new JLabel("Version " + version);
		build.setFont(FontManager.getRunescapeSmallFont());
		build.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		build.setAlignmentX(LEFT_ALIGNMENT);
		content.add(build);

		JScrollPane scroll = new JScrollPane(new ScrollableWrapper(content),
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		SlimScrollBarUI.apply(scroll.getVerticalScrollBar());
		add(scroll, BorderLayout.CENTER);

		// listen on the labels' own parent: the outer panel is wider than the
		// column they actually get, by the scrollbar and viewport insets
		content.addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				reflow();
			}
		});
	}

	private void addSection(JPanel content, String heading, String body)
	{
		JLabel label = new JLabel(heading);
		label.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
		label.setForeground(HEADING);
		label.setAlignmentX(LEFT_ALIGNMENT);
		content.add(label);
		content.add(Box.createVerticalStrut(2));
		paragraph(content, body);
		content.add(Box.createVerticalStrut(10));
	}

	private JLabel paragraph(JPanel content, String text)
	{
		JLabel label = new JLabel();
		label.setFont(FontManager.getRunescapeFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(LEFT_ALIGNMENT);
		content.add(label);
		paragraphs.add(new Paragraph(label, text));
		return label;
	}

	/**
	 * Re-wraps every paragraph to the width the text column actually has.
	 *
	 * The lines are broken with FontMetrics rather than a CSS {@code width},
	 * because Swing's HTML renderer does not treat a CSS pixel as one of the
	 * component's pixels — under display scaling a "168px" column paints
	 * around 218px wide, which is what kept clipping the end of every line
	 * no matter how the container was measured. FontMetrics measures in the
	 * same space the text is painted in, so a line that measures as fitting
	 * does fit.
	 */
	private void reflow()
	{
		int width = content.getWidth() - SIDE_PADDING;
		if (width <= 0 || width == renderedWidth)
		{
			return;
		}
		renderedWidth = width;
		for (Paragraph paragraph : paragraphs)
		{
			JLabel label = paragraph.label;
			label.setText(wrapToWidth(paragraph.text, label.getFontMetrics(label.getFont()), width));
			label.setMaximumSize(new Dimension(width, Integer.MAX_VALUE));
		}
		revalidate();
	}

	/** Greedy word wrap producing explicit &lt;br&gt; breaks — no CSS widths involved. */
	static String wrapToWidth(String text, FontMetrics metrics, int maxWidth)
	{
		StringBuilder html = new StringBuilder("<html>");
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(candidate) > maxWidth)
			{
				html.append(escape(line.toString())).append("<br>");
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		return html.append(escape(line.toString())).append("</html>").toString();
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

