package com.wikigearsetups.wiki;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Parses the "example setups" idiom raid pages share: a wikitable whose
 * header cells label complete loadout columns, with parallel rows of
 * {{Equipment}}, {{Inventory}} and {{Rune pouch}} templates — CoX/ToA use
 * one table of tier columns, the ToB guide one table of role columns per
 * mode/tier section. Section headings above each table become the setup's
 * path so the UI can offer them as cascading choices.
 *
 * Table markup is only meaningful at template depth 0 — an {{Equipment}}
 * body is full of lines starting with '|' that are template params, not
 * cells.
 */
@Slf4j
public class ExampleSetupParser
{
	private static final Pattern HEADING = Pattern.compile("^(={2,6})\\s*(.+?)\\s*\\1\\s*$");

	private static final Map<String, EquipSlot> EQUIPMENT_PARAMS = new HashMap<>();

	static
	{
		EQUIPMENT_PARAMS.put("head", EquipSlot.HEAD);
		EQUIPMENT_PARAMS.put("cape", EquipSlot.CAPE);
		EQUIPMENT_PARAMS.put("neck", EquipSlot.NECK);
		EQUIPMENT_PARAMS.put("ammo", EquipSlot.AMMO);
		EQUIPMENT_PARAMS.put("weapon", EquipSlot.WEAPON);
		EQUIPMENT_PARAMS.put("torso", EquipSlot.BODY);
		EQUIPMENT_PARAMS.put("body", EquipSlot.BODY);
		EQUIPMENT_PARAMS.put("shield", EquipSlot.SHIELD);
		EQUIPMENT_PARAMS.put("legs", EquipSlot.LEGS);
		EQUIPMENT_PARAMS.put("gloves", EquipSlot.HANDS);
		EQUIPMENT_PARAMS.put("hands", EquipSlot.HANDS);
		EQUIPMENT_PARAMS.put("boots", EquipSlot.FEET);
		EQUIPMENT_PARAMS.put("feet", EquipSlot.FEET);
		EQUIPMENT_PARAMS.put("ring", EquipSlot.RING);
	}

	private final InventoryParser inventoryParser = new InventoryParser();

	public List<ExampleSetup> parse(String rawWikitext)
	{
		List<ExampleSetup> setups = new ArrayList<>();
		if (rawWikitext == null || rawWikitext.isEmpty())
		{
			return setups;
		}
		String[] lines = GearSetupParser.normalizeLineEndings(rawWikitext).split("\n", -1);
		String h2 = null;
		String h3 = null;

		for (int i = 0; i < lines.length; i++)
		{
			String line = lines[i];
			Matcher heading = HEADING.matcher(line);
			if (heading.matches())
			{
				String text = GearSetupParser.stripMarkup(heading.group(2));
				if (heading.group(1).length() == 2)
				{
					h2 = text;
					h3 = null;
				}
				else
				{
					h3 = text;
				}
				continue;
			}
			if (line.startsWith("{|"))
			{
				List<String> path = new ArrayList<>();
				if (h2 != null)
				{
					path.add(h2);
				}
				if (h3 != null)
				{
					path.add(h3);
				}
				i = parseTable(lines, i + 1, path, setups);
			}
		}
		return setups;
	}

	/** Consumes table lines from {@code start}; returns the index of its closing line. */
	private int parseTable(String[] lines, int start, List<String> path, List<ExampleSetup> out)
	{
		List<String> headers = new ArrayList<>();
		List<List<StringBuilder>> rows = new ArrayList<>();
		StringBuilder current = null;
		int templateDepth = 0;
		int i = start;

		for (; i < lines.length; i++)
		{
			String line = lines[i];
			if (templateDepth > 0)
			{
				current.append('\n').append(line);
				templateDepth += depthDelta(line);
				continue;
			}
			if (line.startsWith("|}"))
			{
				break;
			}
			if (line.startsWith("|+"))
			{
				continue;
			}
			if (line.startsWith("|-"))
			{
				rows.add(new ArrayList<>());
				current = null;
				continue;
			}
			if (line.startsWith("!"))
			{
				for (String part : line.substring(1).split("!!"))
				{
					headers.add(part.trim());
				}
				current = null;
				continue;
			}
			if (line.startsWith("|"))
			{
				if (rows.isEmpty())
				{
					rows.add(new ArrayList<>());
				}
				List<StringBuilder> row = rows.get(rows.size() - 1);
				for (String part : line.substring(1).split("\\|\\|"))
				{
					current = new StringBuilder(part);
					row.add(current);
				}
				// only the last cell on the line can leave a template open
				templateDepth = Math.max(0, depthDelta(current.toString()));
				continue;
			}
			// continuation: multi-line header labels or free text in a cell
			if (!headers.isEmpty() && rows.isEmpty() && !headers.get(headers.size() - 1).isEmpty()
				&& !line.trim().isEmpty())
			{
				headers.set(headers.size() - 1, headers.get(headers.size() - 1) + " " + line.trim());
			}
			else if (current != null)
			{
				// a template may open here ("|" cell marker on its own line,
				// "{{Equipment" on the next) — track depth or its params get
				// misread as table cells
				current.append('\n').append(line);
				templateDepth = Math.max(0, templateDepth + depthDelta(line));
			}
		}

		emitColumns(headers, rows, path, out);
		return i;
	}

	private void emitColumns(List<String> headers, List<List<StringBuilder>> rows,
		List<String> path, List<ExampleSetup> out)
	{
		for (int col = 0; col < headers.size(); col++)
		{
			String label = GearSetupParser.stripMarkup(headers.get(col)).replaceAll("\\s+", " ").trim();
			if (label.isEmpty())
			{
				continue;
			}
			StringBuilder columnText = new StringBuilder();
			for (List<StringBuilder> row : rows)
			{
				if (col < row.size())
				{
					columnText.append(row.get(col)).append('\n');
				}
			}
			try
			{
				GearSetup gear = parseEquipment(columnText.toString(), label);
				if (gear == null)
				{
					continue;
				}
				List<InventorySetup> inventories = inventoryParser.parse(columnText.toString());
				InventorySetup inventory = inventories.isEmpty() ? null : inventories.get(0);
				out.add(new ExampleSetup(new ArrayList<>(path), label, gear, inventory));
			}
			catch (Exception e)
			{
				log.warn("Skipping malformed example setup column '{}'", label, e);
			}
		}
	}

	/** The first {{Equipment}} template in the text, or null. */
	private static GearSetup parseEquipment(String text, String label)
	{
		int i = 0;
		while ((i = text.indexOf("{{", i)) >= 0)
		{
			int end = GearSetupParser.findTemplateEnd(text, i);
			if (end < 0)
			{
				return null;
			}
			String inner = text.substring(i + 2, end - 2);
			if (!GearSetupParser.templateName(inner).equalsIgnoreCase("equipment"))
			{
				i = end;
				continue;
			}

			Map<EquipSlot, List<RankedItem>> slots = new EnumMap<>(EquipSlot.class);
			for (String part : GearSetupParser.splitTopLevel(inner, '|'))
			{
				int eq = GearSetupParser.indexOfTopLevel(part, '=');
				if (eq < 0)
				{
					continue;
				}
				EquipSlot slot = EQUIPMENT_PARAMS.get(part.substring(0, eq).trim().toLowerCase(Locale.ROOT));
				if (slot == null)
				{
					continue;
				}
				String item = GearSetupParser.stripMarkup(part.substring(eq + 1));
				if (!item.isEmpty() && !item.equalsIgnoreCase("none") && !item.equalsIgnoreCase("n/a"))
				{
					List<RankedItem> single = new ArrayList<>();
					single.add(new RankedItem(item, 1, null));
					slots.put(slot, single);
				}
			}
			return slots.isEmpty() ? null : new GearSetup(label, slots);
		}
		return null;
	}

	/**
	 * {@link InventoryParser} scans the whole page, so on a raid page it also
	 * returns the inventories that belong to example columns. Those are
	 * already paired with their gear and shouldn't appear as standalone
	 * choices for the ranked setups. Matched on slot contents rather than
	 * whole-object equality, because the two parses derive labels differently.
	 */
	public static List<InventorySetup> withoutExampleInventories(List<InventorySetup> pageInventories,
		List<ExampleSetup> examples)
	{
		if (pageInventories.isEmpty() || examples.isEmpty())
		{
			return pageInventories;
		}
		List<List<String>> exampleSlots = new ArrayList<>();
		for (ExampleSetup example : examples)
		{
			if (example.getInventory() != null)
			{
				exampleSlots.add(example.getInventory().getSlots());
			}
		}
		List<InventorySetup> remaining = new ArrayList<>();
		for (InventorySetup inventory : pageInventories)
		{
			if (!exampleSlots.contains(inventory.getSlots()))
			{
				remaining.add(inventory);
			}
		}
		return remaining;
	}

	private static int depthDelta(String line)
	{
		int depth = 0;
		for (int i = 0; i < line.length() - 1; i++)
		{
			if (line.charAt(i) == '{' && line.charAt(i + 1) == '{')
			{
				depth++;
				i++;
			}
			else if (line.charAt(i) == '}' && line.charAt(i + 1) == '}')
			{
				depth--;
				i++;
			}
		}
		return depth;
	}
}

package com.wikigearsetups.wiki;

import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * One parsed {{Recommended equipment}} template: a combat-style label and,
 * per equipment slot, the recommended items ordered by rank ascending
 * (rank 1 = best), appearance order within a rank.
 *
 * {@code paneLabel} is the tabber pane or section heading the template sat
 * under, kept as a fallback for when {@code styleLabel} (the template's own
 * {@code |style=}) is missing or duplicated on the page.
 */
@Value
public class GearSetup
{
	String styleLabel;
	Map<EquipSlot, List<RankedItem>> slots;
	@Nullable
	String paneLabel;

	public GearSetup(String styleLabel, Map<EquipSlot, List<RankedItem>> slots)
	{
		this(styleLabel, slots, null);
	}

	public GearSetup(String styleLabel, Map<EquipSlot, List<RankedItem>> slots, @Nullable String paneLabel)
	{
		this.styleLabel = styleLabel;
		this.slots = slots;
		this.paneLabel = paneLabel;
	}
}

package com.wikigearsetups.wiki;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Extracts {{Recommended equipment}} templates from raw wikitext.
 *
 * Deliberately tolerant: a malformed slot value is logged and skipped, never
 * fatal for the page. Only {{plink}}-family targets count as items — bare
 * wiki links in slot values are prose (see docs/wiki-format.md).
 */
@Slf4j
public class GearSetupParser
{
	private static final String TEMPLATE_NAME = "recommended equipment";
	private static final Pattern SLOT_PARAM = Pattern.compile("([a-z]+)([0-9]+)");
	private static final Pattern HTML_COMMENT = Pattern.compile("<!--.*?-->", Pattern.DOTALL);
	/** A balanced parenthetical qualifying the item that precedes it: "(on task)". */
	private static final Pattern PARENTHETICAL = Pattern.compile("\\(([^()]+)\\)");
	private static final Pattern REF_BODY =
		Pattern.compile("<ref[^>]*>(.*?)</ref>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
	private static final Pattern PIPED_LINK = Pattern.compile("\\[\\[[^\\]|]*\\|([^\\]]*)\\]\\]");
	private static final Pattern PLAIN_LINK = Pattern.compile("\\[\\[([^\\]|]*)\\]\\]");
	private static final Pattern NESTED_TEMPLATE = Pattern.compile("\\{\\{[^{}]*\\}\\}");

	public List<GearSetup> parse(String rawWikitext)
	{
		List<GearSetup> setups = new ArrayList<>();
		if (rawWikitext == null || rawWikitext.isEmpty())
		{
			return setups;
		}
		String wikitext = normalizeLineEndings(rawWikitext);

		int i = 0;
		while ((i = wikitext.indexOf("{{", i)) >= 0)
		{
			int end = findTemplateEnd(wikitext, i);
			if (end < 0)
			{
				i += 2;
				continue;
			}

			String body = wikitext.substring(i + 2, end - 2);
			if (templateName(body).equalsIgnoreCase(TEMPLATE_NAME))
			{
				GearSetup setup = parseSetup(body, setups.size() + 1,
					SectionLabels.precedingLabel(wikitext, i));
				if (setup != null)
				{
					setups.add(setup);
				}
				i = end;
			}
			else
			{
				// step past the opening braces only, so templates nested
				// inside non-matching wrappers (e.g. tabber helpers) are found
				i += 2;
			}
		}
		return setups;
	}

	private GearSetup parseSetup(String templateBody, int index, String paneLabel)
	{
		List<String> parts = splitTopLevel(templateBody, '|');
		String style = null;
		Map<EquipSlot, TreeMap<Integer, List<RankedItem>>> ranked = new EnumMap<>(EquipSlot.class);

		for (int p = 1; p < parts.size(); p++)
		{
			String part = parts.get(p);
			int eq = indexOfTopLevel(part, '=');
			if (eq < 0)
			{
				continue;
			}
			String name = part.substring(0, eq).trim().toLowerCase(Locale.ROOT);
			String value = part.substring(eq + 1);

			try
			{
				if (name.equals("style"))
				{
					String s = stripMarkup(value);
					if (!s.isEmpty())
					{
						style = s;
					}
					continue;
				}

				Matcher m = SLOT_PARAM.matcher(name);
				if (!m.matches())
				{
					continue;
				}
				EquipSlot slot = EquipSlot.fromWikiParam(m.group(1));
				if (slot == null)
				{
					continue;
				}
				int rank = Integer.parseInt(m.group(2));

				List<RankedItem> items = parseItems(value, rank);
				if (!items.isEmpty())
				{
					ranked.computeIfAbsent(slot, k -> new TreeMap<>()).put(rank, items);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Skipping malformed slot param '{}'", name, e);
			}
		}

		Map<EquipSlot, List<RankedItem>> slots = new EnumMap<>(EquipSlot.class);
		int total = 0;
		for (Map.Entry<EquipSlot, TreeMap<Integer, List<RankedItem>>> e : ranked.entrySet())
		{
			List<RankedItem> flat = new ArrayList<>();
			for (List<RankedItem> tier : e.getValue().values())
			{
				flat.addAll(tier);
			}
			slots.put(e.getKey(), flat);
			total += flat.size();
		}

		if (total == 0)
		{
			return null;
		}
		return new GearSetup(style != null ? style : "Setup " + index, slots, paneLabel);
	}

	private List<RankedItem> parseItems(String value, int rank)
	{
		List<RankedItem> items = new ArrayList<>();
		String v = HTML_COMMENT.matcher(value).replaceAll("");

		int i = 0;
		while (i < v.length())
		{
			if (!v.startsWith("{{", i))
			{
				i++;
				continue;
			}
			int end = findTemplateEnd(v, i);
			if (end < 0)
			{
				break;
			}
			String inner = v.substring(i + 2, end - 2);
			String name = templateName(inner).toLowerCase(Locale.ROOT);

			if (name.equals("plink") || name.equals("plinkp") || name.equals("plinkt"))
			{
				String item = firstPositional(inner);
				if (item != null)
				{
					item = stripMarkup(item);
					// a "#" means the target is a page section, never an item —
					// the real name is in txt=, or before the anchor
					List<String> fallbacks = new ArrayList<>();
					addIfPresent(fallbacks, namedParam(inner, "txt"));
					addIfPresent(fallbacks, namedParam(inner, "pic"));
					int anchor = item.indexOf('#');
					if (anchor >= 0)
					{
						String beforeAnchor = item.substring(0, anchor).trim();
						item = fallbacks.isEmpty() ? beforeAnchor : fallbacks.remove(0);
						addIfPresent(fallbacks, beforeAnchor);
					}
					// "+{{plinkp|Trouver parchment}}" marks a companion item
					// (lock the gear at Perdu), not a wearable alternative
					if (!item.isEmpty() && !item.equalsIgnoreCase("n/a") && !item.equalsIgnoreCase("none")
						&& !item.equalsIgnoreCase("trouver parchment") && !isCompanion(v, i))
					{
						items.add(new RankedItem(item, rank, annotationAfter(v, end), fallbacks));
					}
				}
			}
			else if (name.equals("efn") && !items.isEmpty())
			{
				String note = firstPositional(inner);
				if (note != null)
				{
					note = stripMarkup(note);
					if (!note.isEmpty())
					{
						RankedItem last = items.get(items.size() - 1);
						String merged = last.getNote() == null ? note : last.getNote() + "; " + note;
						items.set(items.size() - 1,
							new RankedItem(last.getName(), rank, merged, last.getFallbackNames()));
					}
				}
			}
			i = end;
		}
		return items;
	}

	/**
	 * A companion item rather than a wearable alternative: written attached to
	 * the plus, "{{plink|Fighter torso}}+{{plinkp|Trouver parchment}}".
	 *
	 * The plus must touch the template. Pages also use a <em>spaced</em> plus
	 * to mean "and bring this too" — Fortis Colosseum lists a whole switch
	 * loadout that way ("Osmumten's fang + Bow of faerdhinen + Sanguinesti
	 * staff") — and treating those as companions silently dropped real gear
	 * from the slot.
	 */
	private static boolean isCompanion(String s, int templateStart)
	{
		return templateStart > 0 && s.charAt(templateStart - 1) == '+';
	}

	/**
	 * Plain text between this template and the next, as a note.
	 *
	 * Roughly half the pages qualify a recommendation with a bare
	 * parenthetical — "{{plink|Slayer helmet (i)}} (on task)" — rather than an
	 * {{efn}} footnote. Without this those conditions are invisible, and the
	 * item gets recommended unconditionally.
	 *
	 * Only balanced parentheses and &lt;ref&gt; bodies count, so separators
	 * ("/", "&lt;br&gt;") and the "(or:{{plinkp|…}}" alternative-list opener
	 * yield nothing.
	 */
	static String annotationAfter(String value, int templateEnd)
	{
		int next = value.indexOf("{{", templateEnd);
		String trailing = value.substring(templateEnd, next < 0 ? value.length() : next);
		if (trailing.isEmpty())
		{
			return null;
		}

		StringBuilder note = new StringBuilder();
		Matcher ref = REF_BODY.matcher(trailing);
		while (ref.find())
		{
			append(note, stripMarkup(ref.group(1)));
		}
		Matcher paren = PARENTHETICAL.matcher(REF_BODY.matcher(trailing).replaceAll(""));
		while (paren.find())
		{
			append(note, stripMarkup(paren.group(1)));
		}
		return note.length() == 0 ? null : note.toString();
	}

	private static void append(StringBuilder note, String text)
	{
		if (text != null && !text.trim().isEmpty())
		{
			if (note.length() > 0)
			{
				note.append("; ");
			}
			note.append(text.trim());
		}
	}

	/**
	 * From the index of an opening "{{", returns the index just past its
	 * matching "}}", or -1 if unbalanced.
	 */
	static int findTemplateEnd(String s, int start)
	{
		int depth = 0;
		int i = start;
		while (i < s.length() - 1)
		{
			if (s.charAt(i) == '{' && s.charAt(i + 1) == '{')
			{
				depth++;
				i += 2;
			}
			else if (s.charAt(i) == '}' && s.charAt(i + 1) == '}')
			{
				depth--;
				i += 2;
				if (depth == 0)
				{
					return i;
				}
			}
			else
			{
				i++;
			}
		}
		return -1;
	}

	/** Template name: body text up to the first pipe (or whole body). */
	static String templateName(String templateBody)
	{
		int pipe = templateBody.indexOf('|');
		String name = pipe < 0 ? templateBody : templateBody.substring(0, pipe);
		return name.trim();
	}

	/** First non-empty positional (un-named) parameter of a template body, or null. */
	private static void addIfPresent(List<String> out, String value)
	{
		if (value != null && !value.isEmpty() && !out.contains(value))
		{
			out.add(value);
		}
	}

	/** Value of a named template param ("txt", "pic"), markup stripped, or null. */
	static String namedParam(String templateBody, String param)
	{
		for (String part : splitTopLevel(templateBody, '|'))
		{
			int eq = indexOfTopLevel(part, '=');
			if (eq > 0 && part.substring(0, eq).trim().equalsIgnoreCase(param))
			{
				String value = stripMarkup(part.substring(eq + 1));
				return value.isEmpty() ? null : value;
			}
		}
		return null;
	}

	static String firstPositional(String templateBody)
	{
		List<String> parts = splitTopLevel(templateBody, '|');
		for (int i = 1; i < parts.size(); i++)
		{
			String part = parts.get(i);
			if (indexOfTopLevel(part, '=') < 0 && !part.trim().isEmpty())
			{
				return part.trim();
			}
		}
		return null;
	}

	/** Splits on sep, ignoring occurrences nested inside {{...}} or [[...]]. */
	static List<String> splitTopLevel(String s, char sep)
	{
		List<String> parts = new ArrayList<>();
		int braceDepth = 0;
		int bracketDepth = 0;
		StringBuilder cur = new StringBuilder();
		int i = 0;
		while (i < s.length())
		{
			if (s.startsWith("{{", i))
			{
				braceDepth++;
				cur.append("{{");
				i += 2;
			}
			else if (s.startsWith("}}", i))
			{
				braceDepth = Math.max(0, braceDepth - 1);
				cur.append("}}");
				i += 2;
			}
			else if (s.startsWith("[[", i))
			{
				bracketDepth++;
				cur.append("[[");
				i += 2;
			}
			else if (s.startsWith("]]", i))
			{
				bracketDepth = Math.max(0, bracketDepth - 1);
				cur.append("]]");
				i += 2;
			}
			else if (s.charAt(i) == sep && braceDepth == 0 && bracketDepth == 0)
			{
				parts.add(cur.toString());
				cur.setLength(0);
				i++;
			}
			else
			{
				cur.append(s.charAt(i));
				i++;
			}
		}
		parts.add(cur.toString());
		return parts;
	}

	/** Index of the first top-level occurrence of c, or -1. */
	static int indexOfTopLevel(String s, char c)
	{
		int braceDepth = 0;
		int bracketDepth = 0;
		int i = 0;
		while (i < s.length())
		{
			if (s.startsWith("{{", i))
			{
				braceDepth++;
				i += 2;
			}
			else if (s.startsWith("}}", i))
			{
				braceDepth = Math.max(0, braceDepth - 1);
				i += 2;
			}
			else if (s.startsWith("[[", i))
			{
				bracketDepth++;
				i += 2;
			}
			else if (s.startsWith("]]", i))
			{
				bracketDepth = Math.max(0, bracketDepth - 1);
				i += 2;
			}
			else
			{
				if (s.charAt(i) == c && braceDepth == 0 && bracketDepth == 0)
				{
					return i;
				}
				i++;
			}
		}
		return -1;
	}

	/**
	 * Reduces wiki markup to display text: [[a|b]] -> b, [[a]] -> a, nested
	 * templates dropped, br tags to spaces, whitespace collapsed.
	 */
	/**
	 * Line-based patterns (tabber labels, headings, table markup) must not
	 * see stray carriage returns. The wiki API serves LF, but a fixture
	 * checked out with CRLF — or any future caller — must parse identically.
	 */
	static String normalizeLineEndings(String s)
	{
		return s.indexOf('\r') < 0 ? s : s.replace("\r\n", "\n").replace('\r', '\n');
	}

	static String stripMarkup(String s)
	{
		String out = s;
		String prev;
		do
		{
			prev = out;
			out = NESTED_TEMPLATE.matcher(out).replaceAll("");
		}
		while (!out.equals(prev));
		out = PIPED_LINK.matcher(out).replaceAll("$1");
		out = PLAIN_LINK.matcher(out).replaceAll("$1");
		out = out.replaceAll("(?i)<br\\s*/?>", " ");
		out = out.replaceAll("''+", "");
		out = out.replaceAll("\\s+", " ");
		return out.trim();
	}
}

package com.wikigearsetups.wiki;

import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * Tells a real loadout apart from an inline "for this room, bring this one
 * item" annotation.
 *
 * Across the whole corpus, gear styles are bimodal by slot count: real
 * loadouts fill 8-12 slots, annotations fill 1-2, and <em>nothing</em> fills
 * 3 or 4. That empty band is the wiki's own editing convention, not a tuned
 * threshold — so any cutoff inside it separates the two cleanly. Raids drive
 * this: Chambers of Xeric alone contributes 12 single-item "styles" (Tekton,
 * the Olm claws, …) that would otherwise flood the dropdown as if they were
 * alternatives to your entire setup.
 */
public final class GearSetups
{
	/** Below this a setup is an annotation, not a loadout (see the class note). */
	public static final int MIN_LOADOUT_SLOTS = 3;

	private GearSetups()
	{
	}

	public static boolean isLoadout(GearSetup setup)
	{
		return setup.getSlots().size() >= MIN_LOADOUT_SLOTS;
	}

	/**
	 * Splits a page's setups into the loadouts worth a dropdown entry and the
	 * thin annotation setups.
	 *
	 * A page that is <em>entirely</em> annotations (the Ultimate Ironman
	 * equipment guide uses the template 42 times as an illustration) is left
	 * whole — filtering everything away would blank the panel, which is worse
	 * than a long list. Such a page has no loadout to hang the annotations off
	 * of anyway.
	 */
	public static Partition partition(List<GearSetup> setups)
	{
		List<GearSetup> loadouts = new ArrayList<>();
		List<GearSetup> switches = new ArrayList<>();
		List<Integer> loadoutIndices = new ArrayList<>();
		for (int i = 0; i < setups.size(); i++)
		{
			if (isLoadout(setups.get(i)))
			{
				loadouts.add(setups.get(i));
				loadoutIndices.add(i);
			}
			else
			{
				switches.add(setups.get(i));
			}
		}
		if (loadouts.isEmpty())
		{
			loadoutIndices.clear();
			for (int i = 0; i < setups.size(); i++)
			{
				loadoutIndices.add(i);
			}
			return new Partition(new ArrayList<>(setups), new ArrayList<>(), loadoutIndices);
		}
		return new Partition(loadouts, switches, loadoutIndices);
	}

	/**
	 * {@code loadoutIndices.get(j)} is the position of loadout {@code j} in the
	 * original setup list — used to remap a pairing array computed against the
	 * unfiltered list onto the filtered one.
	 */
	@Value
	public static class Partition
	{
		List<GearSetup> loadouts;
		List<GearSetup> switches;
		List<Integer> loadoutIndices;

		/**
		 * Remaps an inventory-pairing array (indexed by original setup) so it is
		 * indexed by loadout instead. Empty in, empty out — a page with no
		 * positional pairing stays unpaired.
		 */
		public int[] remapPairing(int[] pairing)
		{
			if (pairing.length == 0)
			{
				return pairing;
			}
			int[] remapped = new int[loadouts.size()];
			for (int j = 0; j < loadouts.size(); j++)
			{
				int original = loadoutIndices.get(j);
				remapped[j] = original < pairing.length ? pairing[original] : -1;
			}
			return remapped;
		}
	}
}

package com.wikigearsetups.wiki;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

import static com.wikigearsetups.wiki.GearSetupParser.findTemplateEnd;
import static com.wikigearsetups.wiki.GearSetupParser.indexOfTopLevel;
import static com.wikigearsetups.wiki.GearSetupParser.splitTopLevel;
import static com.wikigearsetups.wiki.GearSetupParser.stripMarkup;
import static com.wikigearsetups.wiki.GearSetupParser.templateName;

/**
 * Extracts {{Inventory}} templates and their trailing {{Rune pouch}}.
 *
 * Slots may be numbered ("|1=Twisted bow", Zulrah style) or positional
 * ("|Giant pouch |Large pouch |...", GotR style) — positional params count
 * empty cells too, preserving grid positions. Labels come from the nearest
 * preceding tabber pane label or section heading, since the template has no
 * style param of its own. A {{Rune pouch}} attaches to the inventory that
 * precedes it.
 */
@Slf4j
public class InventoryParser
{
	private static final int SLOTS = 28;
	private static final int RUNE_SLOTS = 4;

	/**
	 * Joins the candidates of a choice template into one slot value. No item
	 * name contains it, so splitting back out is unambiguous.
	 */
	public static final String CHOICE_SEPARATOR = " / ";

	private static final class Pending
	{
		final String label;
		final List<String> slots;
		List<String> runes = Collections.emptyList();

		Pending(String label, List<String> slots)
		{
			this.label = label;
			this.slots = slots;
		}
	}

	public List<InventorySetup> parse(String rawWikitext)
	{
		List<Pending> pending = new ArrayList<>();
		if (rawWikitext == null || rawWikitext.isEmpty())
		{
			return Collections.emptyList();
		}
		String wikitext = GearSetupParser.normalizeLineEndings(rawWikitext);

		int i = 0;
		while ((i = wikitext.indexOf("{{", i)) >= 0)
		{
			int end = findTemplateEnd(wikitext, i);
			if (end < 0)
			{
				i += 2;
				continue;
			}
			String body = wikitext.substring(i + 2, end - 2);
			String name = templateName(body);
			if (name.equalsIgnoreCase("inventory"))
			{
				List<String> slots = parseSlots(body, SLOTS);
				if (slots != null)
				{
					pending.add(new Pending(labelFor(wikitext, i, pending.size() + 1), slots));
				}
				i = end;
			}
			else if (name.equalsIgnoreCase("rune pouch"))
			{
				List<String> runes = parseSlots(body, RUNE_SLOTS);
				if (runes != null && !pending.isEmpty())
				{
					Pending last = pending.get(pending.size() - 1);
					if (last.runes.isEmpty())
					{
						last.runes = compact(runes);
					}
				}
				i = end;
			}
			else
			{
				i += 2;
			}
		}

		List<InventorySetup> setups = new ArrayList<>(pending.size());
		for (Pending p : pending)
		{
			setups.add(new InventorySetup(p.label, p.slots, p.runes));
		}
		return setups;
	}

	/**
	 * Numbered and positional params both fill slots; positional params count
	 * empty cells so grid positions survive. Returns null when nothing filled.
	 */
	private static List<String> parseSlots(String templateBody, int maxSlots)
	{
		List<String> slots = new ArrayList<>(maxSlots);
		for (int s = 0; s < maxSlots; s++)
		{
			slots.add("");
		}

		List<String> parts = splitTopLevel(templateBody, '|');
		int positional = 0;
		int filled = 0;
		for (int p = 1; p < parts.size(); p++)
		{
			String part = parts.get(p);
			int eq = indexOfTopLevel(part, '=');
			int slot;
			String value;
			if (eq < 0)
			{
				slot = ++positional;
				value = part;
			}
			else
			{
				String name = part.substring(0, eq).trim();
				try
				{
					slot = Integer.parseInt(name);
				}
				catch (NumberFormatException e)
				{
					continue; // align=, buttons=, etc.
				}
				value = part.substring(eq + 1);
			}
			if (slot < 1 || slot > maxSlots)
			{
				continue;
			}

			String item = cleanSlotValue(value);
			if (!item.isEmpty())
			{
				slots.set(slot - 1, item);
				filled++;
			}
		}
		return filled == 0 ? null : slots;
	}

	/** Drops empty cells, preserving order — rune lists have no grid meaning. */
	private static List<String> compact(List<String> slots)
	{
		List<String> out = new ArrayList<>();
		for (String s : slots)
		{
			if (!s.isEmpty())
			{
				out.add(s);
			}
		}
		return out;
	}

	/**
	 * Plain names pass through; a value that is only a placeholder template
	 * ({{Cheap food}}) yields that template's name so it surfaces as
	 * unrecognized downstream instead of vanishing silently.
	 */
	static String cleanSlotValue(String value)
	{
		String stripped = stripQuantity(stripMarkup(value));
		if (stripped.equalsIgnoreCase("placeholder"))
		{
			// a deliberately empty grid cell (Maniacal monkeys write "|16=Placeholder")
			return "";
		}
		if (!stripped.isEmpty())
		{
			return stripped;
		}
		int t = value.indexOf("{{");
		if (t >= 0)
		{
			int end = findTemplateEnd(value, t);
			if (end > 0)
			{
				String body = value.substring(t + 2, end - 2);
				String choices = choiceList(body);
				return choices.isEmpty() ? templateName(body) : choices;
			}
		}
		return "";
	}

	/**
	 * Some templates carry their own candidates rather than naming one item:
	 * {{MinPrice|format=item|link=n|Manta ray|Tuna potato|Anglerfish|Dark
	 * crab}} means "whichever of these is cheapest". Their unnamed parameters
	 * are the candidate list, emitted joined so the resolver can treat it the
	 * same way as a hand-listed placeholder.
	 *
	 * Empty unless there are at least two candidates — a single unnamed
	 * parameter is far more likely to be an argument than a choice.
	 */
	static String choiceList(String templateBody)
	{
		List<String> parts = splitTopLevel(templateBody, '|');
		List<String> choices = new ArrayList<>();
		for (int p = 1; p < parts.size(); p++)
		{
			if (indexOfTopLevel(parts.get(p), '=') >= 0)
			{
				continue; // format=, link=, align= …
			}
			String choice = stripMarkup(parts.get(p));
			if (!choice.isEmpty())
			{
				choices.add(choice);
			}
		}
		return choices.size() < 2 ? "" : String.join(CHOICE_SEPARATOR, choices);
	}

	/**
	 * Strips the two markers the template appends to a name: a stack size
	 * after a backslash ("Blood rune\16000", overwhelmingly in {{Rune pouch}})
	 * and a ";n" noted flag ("Iron ore;n" on restock inventories). Values
	 * carry both ("Shark\200;n"). No item name contains either character, so
	 * everything from the first one on is a marker, not part of the name.
	 */
	static String stripQuantity(String value)
	{
		int cut = value.length();
		int slash = value.indexOf('\\');
		if (slash >= 0)
		{
			cut = slash;
		}
		int semi = value.indexOf(';');
		if (semi >= 0 && semi < cut)
		{
			cut = semi;
		}
		return cut == value.length() ? value : value.substring(0, cut).trim();
	}

	/** The pane/heading that distinguishes this inventory, else "Inventory N". */
	static String labelFor(String wikitext, int templateStart, int index)
	{
		String label = SectionLabels.precedingLabel(wikitext, templateStart);
		return label != null ? label : "Inventory " + index;
	}
}

