package com.wikigearsetups.wiki;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.NavigableMap;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static com.wikigearsetups.wiki.GearSetupParser.stripMarkup;

/**
 * The label a template inherits from the tabber pane or section heading it
 * sits under. Templates carry no name of their own, and the wiki's own
 * `|style=` parameter is missing or duplicated often enough that this is the
 * better distinguisher on many pages ("Melee"/"Melee"/"Melee" as styles, but
 * "Lower Level"/"Dharok's"/"Obsidian" as panes).
 *
 * Shared by {@link InventoryParser} and {@link GearSetupParser} so there is
 * one pane-label pattern, not two that can drift apart.
 */
final class SectionLabels
{
	/**
	 * Tabber pane openers: "<tabber>Label=", "|-|Label=", or the label on a
	 * later line — blank lines between the separator and the label are common
	 * and must not break the match.
	 */
	private static final Pattern PANE_LABEL =
		Pattern.compile("(?m)^(?:<tabber>|\\|-\\|)[ \\t]*(?:\\n[ \\t]*)*([^=\\n|{}]+?)[ \\t]*=");
	private static final Pattern HEADING = Pattern.compile("(?m)^={2,5}\\s*(.+?)\\s*={2,5}\\s*$");

	/**
	 * Headings that describe what a template <em>is</em> rather than which
	 * setup it belongs to. Pages routinely put "==Inventory==" or
	 * "==Equipment==" immediately above every template, which would otherwise
	 * give them all the same label.
	 */
	private static final Set<String> GENERIC = new HashSet<>(Arrays.asList(
		"inventory", "inventories", "equipment", "gear", "setup", "setups",
		"loadout", "loadouts", "items", "recommended equipment"));

	private SectionLabels()
	{
	}

	/**
	 * The nearest preceding pane or heading label that actually distinguishes
	 * this template, or {@code null} if there is none.
	 *
	 * Generic headings are stepped over in favour of the enclosing pane label
	 * further back, and only fall through to the nearest generic one when
	 * nothing better exists — so a page that heads every template
	 * "==Inventory==" still finds its "Melee" / "Magic" pane labels.
	 */
	static String precedingLabel(String wikitext, int templateStart)
	{
		String before = wikitext.substring(0, templateStart);
		NavigableMap<Integer, String> candidates = new TreeMap<>();

		Matcher pane = PANE_LABEL.matcher(before);
		while (pane.find())
		{
			candidates.put(pane.start(), pane.group(1).trim());
		}
		Matcher heading = HEADING.matcher(before);
		while (heading.find())
		{
			candidates.put(heading.start(), stripMarkup(heading.group(1)));
		}

		String nearest = null;
		for (String label : candidates.descendingMap().values())
		{
			if (label.isEmpty())
			{
				continue;
			}
			if (nearest == null)
			{
				nearest = label;
			}
			if (!GENERIC.contains(label.toLowerCase(Locale.ROOT)))
			{
				return label;
			}
		}
		return nearest;
	}
}

package com.wikigearsetups.wiki;

import java.util.Arrays;
import lombok.extern.slf4j.Slf4j;

/**
 * Works out which {{Inventory}} belongs to which {{Recommended equipment}}
 * from their order in the page.
 *
 * Document position is a far stronger signal than the labels are: pages
 * routinely head every inventory "==Inventory==", so half of them carry no
 * distinguishing label at all, while their order is unambiguous. Two shapes
 * cover the pages that do this —
 *
 * <pre>
 *   interleaved   E I E I E I    each setup is followed by its own inventory
 *   blocked       E E E I I I    all the setups, then all the inventories
 * </pre>
 *
 * — and both mean setup <i>i</i> owns inventory <i>i</i>. Anything else
 * (ragged orders like E E I E I) is genuinely ambiguous and gets no pairing,
 * leaving label matching to do its best.
 *
 * The template counts found here must match the number of setups the parsers
 * actually kept, otherwise the indices refer to different things — a template
 * that parsed to nothing is dropped from the model but still appears in the
 * page. A mismatch disables pairing rather than guessing.
 */
@Slf4j
public final class SetupPairing
{
	/** No inventory paired to any setup. */
	public static final int[] NONE = new int[0];

	private SetupPairing()
	{
	}

	/**
	 * Index of the inventory belonging to each setup, or -1 where unknown.
	 * Empty when the page's order carries no usable pairing.
	 */
	public static int[] pair(String rawWikitext, int setupCount, int inventoryCount)
	{
		if (rawWikitext == null || setupCount == 0 || inventoryCount == 0)
		{
			return NONE;
		}

		String order = templateOrder(GearSetupParser.normalizeLineEndings(rawWikitext));
		int setups = count(order, 'E');
		int inventories = count(order, 'I');
		if (setups != setupCount || inventories != inventoryCount)
		{
			// a template we skipped (empty, malformed) would shift every index
			log.debug("pairing skipped: page has {}E/{}I, parsers kept {}/{}",
				setups, inventories, setupCount, inventoryCount);
			return NONE;
		}

		// Interleaved order pairs by adjacency, so a spare template at the end
		// is harmless. Blocked order pairs by index alone, and with unequal
		// counts there is no way to tell which setup the spare belongs to.
		boolean pairable = isInterleaved(order)
			|| (isBlocked(order) && setupCount == inventoryCount);
		if (!pairable)
		{
			return NONE;
		}

		int[] pairing = new int[setupCount];
		Arrays.fill(pairing, -1);
		for (int i = 0; i < setupCount && i < inventoryCount; i++)
		{
			pairing[i] = i;
		}
		return pairing;
	}

	/** The page's equipment and inventory templates as a string like "EIEIEI". */
	static String templateOrder(String wikitext)
	{
		StringBuilder order = new StringBuilder();
		int i = 0;
		while ((i = wikitext.indexOf("{{", i)) >= 0)
		{
			int end = GearSetupParser.findTemplateEnd(wikitext, i);
			if (end < 0)
			{
				i += 2;
				continue;
			}
			String name = GearSetupParser.templateName(wikitext.substring(i + 2, end - 2));
			if (name.equalsIgnoreCase("recommended equipment"))
			{
				order.append('E');
				i = end;
			}
			else if (name.equalsIgnoreCase("inventory"))
			{
				order.append('I');
				i = end;
			}
			else
			{
				// step inside: raid tables nest {{Equipment}} and {{Inventory}}
				// within wikitable rows, and those still count
				i += 2;
			}
		}
		return order.toString();
	}

	/** "EIEIEI" — every setup immediately followed by its inventory. */
	static boolean isInterleaved(String order)
	{
		if (order.length() % 2 != 0)
		{
			return false;
		}
		for (int i = 0; i < order.length(); i += 2)
		{
			if (order.charAt(i) != 'E' || order.charAt(i + 1) != 'I')
			{
				return false;
			}
		}
		return order.length() > 0;
	}

	/** "EEEIII" — every setup before every inventory. */
	static boolean isBlocked(String order)
	{
		int firstInventory = order.indexOf('I');
		return firstInventory > 0
			&& order.indexOf('E', firstInventory) < 0
			&& order.lastIndexOf('I') == order.length() - 1;
	}

	private static int count(String s, char c)
	{
		int n = 0;
		for (int i = 0; i < s.length(); i++)
		{
			if (s.charAt(i) == c)
			{
				n++;
			}
		}
		return n;
	}
}

package com.wikigearsetups.wiki;

import java.util.List;
import lombok.Value;

/**
 * Decides which of a page's two formats to offer first: the complete example
 * loadout columns, or the ranked recommendation tables. Pages differ — some
 * keep meticulous tabber setups and a token example table, others the
 * reverse — so the default is scored per page rather than fixed.
 *
 * Scoring is deliberately parse-time only: no item index, no game state, no
 * network. A default that changed depending on whether the player was logged
 * in would be impossible to explain, and an unexplainable default is worse
 * than an occasionally suboptimal one. It measures completeness, which is
 * observable; it does not try to judge editorial accuracy, which isn't.
 */
public final class SourceScorer
{
	/** Below this the two sources are close enough that neither is worth labelling. */
	private static final double DECISIVE_MARGIN = 2.0;

	private static final double INVENTORY_BONUS = 3.0;
	private static final double RUNES_BONUS = 1.0;
	private static final double DEPTH_BONUS = 2.0;
	private static final double DEPTH_THRESHOLD = 1.5;

	@Value
	public static class Result
	{
		double exampleScore;
		double rankedScore;
		boolean preferExamples;

		/** True when the winner leads by enough to be worth telling the user about. */
		public boolean isDecisive()
		{
			return Math.abs(exampleScore - rankedScore) >= DECISIVE_MARGIN;
		}
	}

	private SourceScorer()
	{
	}

	/**
	 * {@code rankedInventories} must already have example-owned inventories
	 * removed (see {@link ExampleSetupParser#withoutExampleInventories}),
	 * otherwise both sources score the inventory bonus on every raid page and
	 * the signal is worthless.
	 */
	public static Result score(List<ExampleSetup> examples, List<GearSetup> ranked,
		List<InventorySetup> rankedInventories)
	{
		double exampleScore = scoreExamples(examples);
		double rankedScore = scoreRanked(ranked, rankedInventories);
		// ties favour examples: complete concrete loadouts are the more
		// intuitive starting point, and enrichment gives them ranked depth anyway
		return new Result(exampleScore, rankedScore, exampleScore >= rankedScore);
	}

	private static double scoreExamples(List<ExampleSetup> examples)
	{
		if (examples.isEmpty())
		{
			return 0;
		}
		double slots = 0;
		int withInventory = 0;
		boolean runes = false;
		for (ExampleSetup example : examples)
		{
			slots += example.getGear().getSlots().size();
			InventorySetup inventory = example.getInventory();
			if (inventory != null)
			{
				withInventory++;
				runes |= !inventory.getRunes().isEmpty();
			}
		}
		double score = slots / examples.size();
		if (withInventory * 2 >= examples.size())
		{
			score += INVENTORY_BONUS;
		}
		return runes ? score + RUNES_BONUS : score;
	}

	private static double scoreRanked(List<GearSetup> ranked, List<InventorySetup> rankedInventories)
	{
		if (ranked.isEmpty())
		{
			return 0;
		}
		double slots = 0;
		double alternatives = 0;
		for (GearSetup setup : ranked)
		{
			slots += setup.getSlots().size();
			for (List<RankedItem> slot : setup.getSlots().values())
			{
				alternatives += slot.size();
			}
		}
		double score = slots / ranked.size();
		if (!rankedInventories.isEmpty())
		{
			score += INVENTORY_BONUS;
			for (InventorySetup inventory : rankedInventories)
			{
				if (!inventory.getRunes().isEmpty())
				{
					score += RUNES_BONUS;
					break;
				}
			}
		}
		// several alternatives per slot is real adaptivity the examples only
		// inherit second-hand through enrichment
		if (slots > 0 && alternatives / slots > DEPTH_THRESHOLD)
		{
			score += DEPTH_BONUS;
		}
		return score;
	}
}

package com.wikigearsetups.wiki;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Async OSRS Wiki MediaWiki API client. All requests go through OkHttp's
 * dispatcher (never the client thread) and carry a descriptive User-Agent as
 * required by wiki API policy. Page wikitext is cached in-memory.
 */
@Slf4j
@Singleton
public class WikiClient
{
	static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	// wiki policy wants a way to reach the maintainer; the repo's issue tracker
	// serves that without putting a personal address in every outbound request
	static final String USER_AGENT =
		"wiki-gear-setups RuneLite plugin (https://github.com/Jiimbones/wiki-gear-setups)";
	private static final Duration CACHE_TTL = Duration.ofMinutes(15);

	private final OkHttpClient http;
	private final Gson gson;
	private final ConcurrentMap<String, CachedPage> pageCache = new ConcurrentHashMap<>();
	private volatile CompletableFuture<Set<String>> petNames;

	@Inject
	public WikiClient(OkHttpClient http, Gson gson)
	{
		// the injected client has no call timeout; a hung wiki should fail
		// fast enough for the panel to show something useful
		this.http = http.newBuilder().callTimeout(Duration.ofSeconds(15)).build();
		this.gson = gson;
	}

	public CompletableFuture<String> getPageWikitext(String title)
	{
		CachedPage cached = pageCache.get(title);
		if (cached != null && cached.getFetchedAt().plus(CACHE_TTL).isAfter(Instant.now()))
		{
			return CompletableFuture.completedFuture(cached.getWikitext());
		}

		HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", "wikitext")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.build();

		return fetchJson(url).thenApply(json ->
		{
			String wikitext = extractWikitext(json);
			pageCache.put(title, new CachedPage(wikitext, Instant.now()));
			return wikitext;
		}).handle((wikitext, err) ->
		{
			// wiki down: a stale cached copy beats an error
			if (err != null)
			{
				CachedPage stale = pageCache.get(title);
				if (stale != null)
				{
					log.debug("Serving stale wiki page '{}' after fetch failure", title, err);
					return stale.getWikitext();
				}
				throw new java.util.concurrent.CompletionException(err);
			}
			return wikitext;
		});
	}

	/**
	 * Searches only pages that actually contain a gear table, via the
	 * CirrusSearch hastemplate keyword — status-effect and lore pages (e.g.
	 * "Venom" for a zulrah search) never show up.
	 */
	public CompletableFuture<List<SearchResult>> search(String query)
	{
		HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", query + " hastemplate:\"Recommended equipment\"")
			.addQueryParameter("srlimit", "10")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		return fetchJson(url).thenApply(WikiClient::extractSearchResults);
	}

	/**
	 * Every pet the wiki knows about, so a boss's pet can be told apart from
	 * the jars and clue scrolls it shares a "Tertiary" section with (their
	 * names follow no pattern — Olmlet, Lil' zik, Vorki). Fetched at most
	 * once per session; failures resolve empty rather than propagating,
	 * since this only decides a default icon.
	 */
	public CompletableFuture<Set<String>> petNames()
	{
		CompletableFuture<Set<String>> cached = petNames;
		if (cached != null)
		{
			return cached;
		}
		synchronized (this)
		{
			if (petNames == null)
			{
				HttpUrl url = API.newBuilder()
					.addQueryParameter("action", "query")
					.addQueryParameter("list", "categorymembers")
					.addQueryParameter("cmtitle", "Category:Pets")
					.addQueryParameter("cmlimit", "500")
					.addQueryParameter("format", "json")
					.addQueryParameter("formatversion", "2")
					.build();
				petNames = fetchJson(url)
					.thenApply(WikiClient::extractCategoryMembers)
					.exceptionally(e ->
					{
						log.debug("Pet category lookup failed", e);
						return Collections.emptySet();
					});
			}
			return petNames;
		}
	}

	static Set<String> extractCategoryMembers(JsonObject json)
	{
		Set<String> names = new LinkedHashSet<>();
		JsonObject query = json.getAsJsonObject("query");
		if (query == null)
		{
			return names;
		}
		JsonArray members = query.getAsJsonArray("categorymembers");
		if (members == null)
		{
			return names;
		}
		for (JsonElement el : members)
		{
			JsonElement title = el.getAsJsonObject().get("title");
			if (title != null)
			{
				names.add(title.getAsString());
			}
		}
		return names;
	}

	private CompletableFuture<JsonObject> fetchJson(HttpUrl url)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		CompletableFuture<JsonObject> future = new CompletableFuture<>();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						future.completeExceptionally(new IOException("Wiki API HTTP " + response.code()));
						return;
					}
					JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
					if (json == null)
					{
						future.completeExceptionally(new IOException("Empty wiki API response"));
						return;
					}
					if (json.has("error"))
					{
						JsonObject error = json.getAsJsonObject("error");
						JsonElement info = error.get("info");
						future.completeExceptionally(new IOException(
							"Wiki API error: " + (info != null ? info.getAsString() : error.toString())));
						return;
					}
					future.complete(json);
				}
				catch (Exception e)
				{
					future.completeExceptionally(e);
				}
			}
		});
		return future;
	}

	static String extractWikitext(JsonObject json)
	{
		JsonObject parse = json.getAsJsonObject("parse");
		if (parse == null || !parse.has("wikitext"))
		{
			throw new IllegalStateException("Wiki API response missing parse.wikitext");
		}
		return parse.get("wikitext").getAsString();
	}

	static List<SearchResult> extractSearchResults(JsonObject json)
	{
		List<SearchResult> results = new ArrayList<>();
		JsonObject query = json.getAsJsonObject("query");
		if (query == null)
		{
			return results;
		}
		JsonArray search = query.getAsJsonArray("search");
		if (search == null)
		{
			return results;
		}
		for (JsonElement el : search)
		{
			JsonObject o = el.getAsJsonObject();
			results.add(new SearchResult(o.get("title").getAsString(), o.get("pageid").getAsInt()));
		}
		return results;
	}

	@Value
	private static class CachedPage
	{
		String wikitext;
		Instant fetchedAt;
	}
}

