			ANCESTRAL_HAT, r.getPicks().get(0).getItemId());
	}

	@Test
	public void informationalNotesAreNotTreatedAsSlayerConditional()
	{
		assertFalse(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Serpentine helm", 1, "Negates the need to bring anti-venom potions")));
		assertTrue(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Slayer helmet (i)", 1, "If on a slayer task")));
	}

	/**
	 * Pages write the task condition as a bare "(on task)" as often as they
	 * write a full "Only while on a Slayer task" footnote. Requiring the word
	 * "slayer" missed the short form on Graardor, KQ, Cerberus and Zulrah.
	 */
	@Test
	public void bareOnTaskParentheticalGatesLikeAFootnote()
	{
		assertTrue(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Slayer helmet (i)", 1, "on task")));
		assertTrue(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Slayer helmet (i)", 1, "if on task")));
		assertTrue(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Slayer helmet (i)", 1, "task only")));
		assertTrue(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Slayer helmet (i)", 1, "Only while on a Slayer task.")));
	}

	@Test
	public void unrelatedNotesAreNotTaskConditions()
	{
		assertFalse(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Serpentine helm", 1, "Better than the Neitiznot faceguard")));
		assertFalse(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Crystal helm", 1, "With full crystal and a bow of Faerdhinen.")));
		assertFalse(OwnershipResolver.isSlayerTaskConditional(
			new RankedItem("Torva full helm", 1, null)));
	}

	/**
	 * The four false positives from the full-corpus audit. Broadening the
	 * match to catch "(on task)" also caught notes that merely mention a task
	 * — and silently hiding a correct item is worse than the bug it replaced.
	 */
	@Test
	public void offTaskNoteIsNeverAGate()
	{
		// Dual macuahuitl on the Custodian stalker page — explicitly off-task
		assertFalse(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Dual macuahuitl", 1,
			"With set effect, off-task. On a slayer task, using a Slayer helm and a slash weapon")));
	}

	@Test
	public void noteNamingADifferentTaskItemDoesNotGateThisItem()
	{
		// Amulet of rancour on KBD — the condition is about the helmet
		assertFalse(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Amulet of rancour", 1,
			"Downgrade to an amulet of glory if bringing a Slayer helmet (i) on task.")));
		// Salve amulet (e) on Vorkath — the note is about the slayer helm's DPS
		assertFalse(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Salve amulet (e)", 1,
			"DPS is slightly higher in max melee gear with slayer helm (i) and amulet")));
	}

	/** But a slayer item whose own note names it still gates. */
	@Test
	public void slayerHelmetWithSelfNamingNoteStillGates()
	{
		assertTrue(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Slayer helmet (i)", 1,
			"Only on a Slayer task.")));
		assertTrue(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Black mask (i)", 1,
			"On task only")));
	}

	@Test
	public void taskConditionWithAnOrEscapeHatchIsNotAGate()
	{
		// Toxic blowpipe on Royal Titans — a condition with an alternative
		assertFalse(OwnershipResolver.isSlayerTaskConditional(new RankedItem("Toxic blowpipe", 1,
			"If on task, or have 8 ranged strength aside from BP & darts, even Amethyst darts")));
	}

	@Test
	public void bareOnTaskMakesTheCheckboxAppear()
	{
		GearSetup s = setup(EquipSlot.HEAD,
			new RankedItem("Slayer helmet (i)", 1, "on task"),
			new RankedItem("Neitiznot faceguard", 2, null));
		assertTrue(OwnershipResolver.hasSlayerConditional(s));
	}

	/** The tooltip surfaces the wiki's own wording, one line per task item. */
	@Test
	public void slayerConditionalNotesPairItemsWithTheirWording()
	{
		GearSetup s = setup(EquipSlot.HEAD,
			new RankedItem("Slayer helmet (i)", 1, "When on a greater demon Slayer task."),
			new RankedItem("Neitiznot faceguard", 2, null));

		assertEquals(Collections.singletonList("Slayer helmet (i) — When on a greater demon Slayer task."),
			OwnershipResolver.slayerConditionalNotes(s));
	}

	@Test
	public void slayerConditionalNotesAreEmptyWhenNothingIsGated()
	{
		GearSetup s = setup(EquipSlot.HEAD, new RankedItem("Torva full helm", 1, null));
		assertTrue(OwnershipResolver.slayerConditionalNotes(s).isEmpty());
	}

	/**
	 * Fortis Colosseum lists a melee weapon, a bow of faerdhinen and a staff
	 * in one slot as a switch loadout. Only one can win the slot, but the
	 * crystal armour is still correct — the bow is carried.
	 */
	@Test
	public void crystalArmourSurvivesWhenTheBowIsASwitchThatLostTheSlot()
	{
		int fang = 26219;
		OwnershipResolver r = new OwnershipResolver(new ItemResolver(FakeItemNameIndex.of(
			CRYSTAL_BODY, "Crystal body", BOWFA, "Bow of faerdhinen", fang, "Osmumten's fang")));

		Map<EquipSlot, List<RankedItem>> slots = new EnumMap<>(EquipSlot.class);
		slots.put(EquipSlot.WEAPON, Arrays.asList(
			new RankedItem("Osmumten's fang", 1, null),
			new RankedItem("Bow of faerdhinen", 1, null)));
		slots.put(EquipSlot.BODY, Collections.singletonList(new RankedItem("Crystal body", 1, null)));

		SetupResolution res = r.resolve(new GearSetup("Budget", slots),
			owned(CRYSTAL_BODY, BOWFA, fang), MissingGearBehavior.OMIT, false);

		boolean crystalKept = false;
		for (SlotPick pick : res.getPicks())
		{
			crystalKept |= pick.getItemId() == CRYSTAL_BODY;
		}
		assertTrue("crystal body should survive a carried bow of faerdhinen", crystalKept);
	}

	/** Armour is not swapped mid-fight, so those groups stay strict. */
	@Test
	public void armourSetGateIsStillStrict()
	{
		GearSetup s = setup(EquipSlot.BODY, new RankedItem("Crystal body", 1, null));
		assertTrue("no bow owned: crystal must go",
			setResolver().resolve(s, owned(CRYSTAL_BODY), MissingGearBehavior.OMIT, false)
				.getPicks().isEmpty());
	}
}

package com.wikigearsetups.items;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Map-backed index for tests. Use real item ids so ItemVariationMapping works. */
public class FakeItemNameIndex implements ItemNameIndex
{
	private final Map<Integer, String> names = new HashMap<>();
	private final Map<String, List<Integer>> byName = new HashMap<>();

	/** Alternating id, name pairs. */
	public static FakeItemNameIndex of(Object... idNamePairs)
	{
		FakeItemNameIndex index = new FakeItemNameIndex();
		for (int i = 0; i < idNamePairs.length; i += 2)
		{
			index.add((Integer) idNamePairs[i], (String) idNamePairs[i + 1]);
		}
		return index;
	}

	public void add(int id, String name)
	{
		names.put(id, name);
		byName.computeIfAbsent(ItemNames.normalize(name), k -> new ArrayList<>()).add(id);
	}

	@Override
	public List<Integer> idsByName(String normalizedName)
	{
		return byName.getOrDefault(normalizedName, Collections.emptyList());
	}

	@Override
	public String nameById(int itemId)
	{
		return names.get(itemId);
	}

	@Override
	public boolean isReady()
	{
		return true;
	}
}

package com.wikigearsetups.items;

import java.util.List;
import java.util.Optional;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Names the wiki uses that no item carries. Each of these was found failing
 * to resolve on a real page, so the point is that the generic name reaches
 * the concrete items — not which one wins, which is ownership's job.
 */
public class ItemAliasesTest
{
	@Test
	public void blessedDhideAcceptsEveryGodsVersion()
	{
		List<String> body = ItemAliases.genericFor("Blessed d'hide body");
		assertTrue(body.contains("Guthix d'hide body"));
		assertTrue(body.contains("Armadyl d'hide body"));
		assertEquals("all six gods", 6, body.size());
	}

	/** Pages write the same slot half a dozen ways; all of them must land. */
	@Test
	public void everySpellingOfAGodDhideSlotResolvesToTheSameItems()
	{
		List<String> canonical = ItemAliases.genericFor("Blessed d'hide body");
		assertEquals(canonical, ItemAliases.genericFor("Blessed body"));
		assertEquals(canonical, ItemAliases.genericFor("Blessed dragonhide body"));

		List<String> bracers = ItemAliases.genericFor("Blessed bracers");
		assertEquals(bracers, ItemAliases.genericFor("Blessed vambraces"));
		assertFalse(bracers.isEmpty());
	}

	/** "{{plink|Blessed_bracers}}" — a URL-style link must still normalize. */
	@Test
	public void underscoresInLinksNormalizeToSpaces()
	{
		assertEquals(ItemNames.normalize("Blessed bracers"), ItemNames.normalize("Blessed_bracers"));
		assertFalse(ItemAliases.genericFor("Blessed_bracers").isEmpty());
	}

	@Test
	public void blessingsCoverTheSixGods()
	{
		assertEquals(6, ItemAliases.genericFor("Blessing").size());
		assertTrue(ItemAliases.genericFor("Blessing").contains("Holy blessing"));
	}

	/** Diary rewards are numbered in game; best tier first so it's preferred. */
	@Test
	public void diaryRewardsListTheirTiersHighestFirst()
	{
		assertEquals(java.util.Arrays.asList(
			"Ardougne cloak 4", "Ardougne cloak 3", "Ardougne cloak 2", "Ardougne cloak 1"),
			ItemAliases.genericFor("Ardougne cloak"));
		assertEquals("Explorer's ring 4", ItemAliases.genericFor("Explorer's ring").get(0));
		assertEquals("Rada's blessing 4", ItemAliases.genericFor("Rada's blessing").get(0));
	}

	@Test
	public void wintertodtWarmClothingHasConcreteCandidates()
	{
		List<String> warm = ItemAliases.genericFor("Warm clothing");
		assertTrue(warm.contains("Bruma torch"));
		assertTrue(warm.contains("Warm gloves"));
	}

	@Test
	public void unknownNamesStayUnknown()
	{
		assertTrue(ItemAliases.genericFor("Twisted bow").isEmpty());
	}

	/** Generic names only apply when the exact name failed, so nothing regresses. */
	@Test
	public void aRealItemNameStillResolvesExactly()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			11826, "Armadyl helmet", 10370, "Guthix d'hide body");
		ItemResolver resolver = new ItemResolver(index);

		Optional<ResolvedItem> exact = resolver.resolve("Armadyl helmet");
		assertTrue(exact.isPresent());
		assertEquals(11826, exact.get().getPrimaryId());
	}

	@Test
	public void aGenericNameResolvesThroughToAConcreteItem()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(10370, "Guthix d'hide body");
		ItemResolver resolver = new ItemResolver(index);

		Optional<ResolvedItem> resolved = resolver.resolve("Blessed d'hide body");
		assertTrue("generic name should reach the concrete item", resolved.isPresent());
		assertTrue(resolved.get().getAcceptableIds().contains(10370));
	}

	/** "God blessing" is another family name for the same six items. */
	@Test
	public void godBlessingResolvesToAConcreteBlessing()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(20220, "Holy blessing");
		ItemResolver resolver = new ItemResolver(index);
		assertTrue(resolver.resolve("God blessing").isPresent());
	}

	/** A bare trailing count and a leading "Open " both fall back to the item. */
	@Test
	public void quantityAndOpenStatePrefixFallBackToTheItem()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(995, "Coins", 13226, "Herb sack");
		ItemResolver resolver = new ItemResolver(index);

		assertEquals(995, resolver.resolve("Coins 10000").get().getPrimaryId());
		assertEquals(13226, resolver.resolve("Open herb sack").get().getPrimaryId());
	}

	/** The strips are last-resort: a genuinely numbered item resolves as itself. */
	@Test
	public void numberedItemsStillResolveExactlyFirst()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			13124, "Ardougne cloak 4", 13123, "Ardougne cloak 3");
		ItemResolver resolver = new ItemResolver(index);
		assertEquals(13124, resolver.resolve("Ardougne cloak 4").get().getPrimaryId());
	}

	/**
	 * Ornament kits and Echo recolours are cosmetic — owning the decorated
	 * version satisfies a recommendation for the base item.
	 */
	@Test
	public void echoRecolourSatisfiesTheBaseItem()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			26241, "Virtus mask", 28001, "Echo virtus mask");
		ItemResolver resolver = new ItemResolver(index);
		assertTrue("owned Echo virtus mask should satisfy a Virtus mask rec",
			resolver.resolve("Virtus mask").get().getAcceptableIds().contains(28001));
	}

	@Test
	public void ornamentKitSuffixSatisfiesTheBaseItem()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			6585, "Amulet of fury", 12436, "Amulet of fury (or)");
		ItemResolver resolver = new ItemResolver(index);
		assertTrue(resolver.resolve("Amulet of fury").get().getAcceptableIds().contains(12436));
	}

	/** Gilded, trimmed, heraldic and Deadman are all cosmetic same-tier copies. */
	@Test
	public void gildedTrimmedHeraldicAndDeadmanSatisfyTheBase()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			1163, "Rune full helm",
			2619, "Rune full helm (g)",
			2627, "Rune full helm (t)",
			10306, "Rune full helm (h1)",
			11838, "Bandos godsword",
			30000, "Bandos godsword (deadman)");
		ItemResolver resolver = new ItemResolver(index);

		java.util.Set<Integer> helm = resolver.resolve("Rune full helm").get().getAcceptableIds();
		assertTrue("gilded", helm.contains(2619));
		assertTrue("trimmed", helm.contains(2627));
		assertTrue("heraldic", helm.contains(10306));
		assertTrue("deadman", resolver.resolve("Bandos godsword").get().getAcceptableIds().contains(30000));
	}

	/** Dyes are listed explicitly because their prefixes are ordinary words. */
	@Test
	public void dyedVariantsSatisfyTheBaseItem()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(
			26233, "Ancient sceptre", 28262, "Shadow ancient sceptre",
			26382, "Torva full helm", 27622, "Sanguine torva full helm",
			22486, "Scythe of vitur", 28338, "Holy scythe of vitur");
		ItemResolver resolver = new ItemResolver(index);

		assertTrue(resolver.resolve("Ancient sceptre").get().getAcceptableIds().contains(28262));
		assertTrue(resolver.resolve("Torva full helm").get().getAcceptableIds().contains(27622));
		assertTrue(resolver.resolve("Scythe of vitur").get().getAcceptableIds().contains(28338));
	}

	/** The base item still resolves as itself — no regression from the extra lookups. */
	@Test
	public void baseItemsAreUnaffectedWhenNoOrnamentExists()
	{
		FakeItemNameIndex index = FakeItemNameIndex.of(26241, "Virtus mask");
		ItemResolver resolver = new ItemResolver(index);
		assertEquals(26241, resolver.resolve("Virtus mask").get().getPrimaryId());
	}
}

package com.wikigearsetups.items;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Uses real item ids so the real ItemVariationMapping data (bundled with the
 * runelite client jar) drives variation expansion.
 */
public class ItemResolverTest
{
	// Barrows: karil's leathertop group = [4736, 4940..4944, 23632]
	private static final int KARILS_LEATHERTOP = 4736;
	private static final int KARILS_LEATHERTOP_100 = 4940;
	private static final int KARILS_LEATHERTOP_0 = 4944;
	private static final int KARILS_LEATHERTOP_LMS = 23632;

	// black mask group merges plain, charged, and imbued tiers
	private static final int BLACK_MASK = 8921;
	private static final int BLACK_MASK_10 = 8901;
	private static final int BLACK_MASK_I = 11784;
	private static final int BLACK_MASK_10_I = 11774;

	// slayer helmet group merges plain, imbued, and recolors
	private static final int SLAYER_HELMET = 11864;
	private static final int SLAYER_HELMET_I = 11865;
	private static final int BLACK_SLAYER_HELMET = 19639;
	private static final int BLACK_SLAYER_HELMET_I = 19641;

	// abyssal whip group includes recolors
	private static final int ABYSSAL_WHIP = 4151;
	private static final int VOLCANIC_ABYSSAL_WHIP = 12773;
	private static final int FROZEN_ABYSSAL_WHIP = 12774;

	private static ItemResolver resolver(Object... idNamePairs)
	{
		return new ItemResolver(FakeItemNameIndex.of(idNamePairs));
	}

	@Test
	public void degradationStatesAreAccepted()
	{
		ItemResolver r = resolver(
			KARILS_LEATHERTOP, "Karil's leathertop",
			KARILS_LEATHERTOP_100, "Karil's leathertop 100",
			KARILS_LEATHERTOP_0, "Karil's leathertop 0");
		ResolvedItem item = r.resolve("Karil's leathertop").orElseThrow(AssertionError::new);
		assertEquals(KARILS_LEATHERTOP, item.getPrimaryId());
		assertTrue(item.getAcceptableIds().contains(KARILS_LEATHERTOP_100));
		assertTrue(item.getAcceptableIds().contains(KARILS_LEATHERTOP_0));
	}

	@Test
	public void sameNameDuplicateIsAcceptedViaVariations()
	{
		ItemResolver r = resolver(
			KARILS_LEATHERTOP, "Karil's leathertop",
			KARILS_LEATHERTOP_LMS, "Karil's leathertop");
		ResolvedItem item = r.resolve("Karil's leathertop").orElseThrow(AssertionError::new);
		assertTrue(item.getAcceptableIds().contains(KARILS_LEATHERTOP));
		assertTrue(item.getAcceptableIds().contains(KARILS_LEATHERTOP_LMS));
	}

	@Test
	public void lowerTierNeverSatisfiesImbuedRecommendation()
	{
		ItemResolver r = resolver(
			BLACK_MASK, "Black mask",
			BLACK_MASK_10, "Black mask (10)",
			BLACK_MASK_I, "Black mask (i)",
			BLACK_MASK_10_I, "Black mask (10) (i)");
		ResolvedItem item = r.resolve("Black mask (i)").orElseThrow(AssertionError::new);
		assertTrue(item.getAcceptableIds().contains(BLACK_MASK_I));
		assertTrue("charged imbued satisfies imbued", item.getAcceptableIds().contains(BLACK_MASK_10_I));
		assertFalse("plain must not satisfy imbued", item.getAcceptableIds().contains(BLACK_MASK));
		assertFalse("charged plain must not satisfy imbued", item.getAcceptableIds().contains(BLACK_MASK_10));
	}

	@Test
	public void upgradeTierSatisfiesPlainRecommendation()
	{
		ItemResolver r = resolver(
			BLACK_MASK, "Black mask",
			BLACK_MASK_10, "Black mask (10)",
			BLACK_MASK_I, "Black mask (i)",
			BLACK_MASK_10_I, "Black mask (10) (i)");
		ResolvedItem item = r.resolve("Black mask").orElseThrow(AssertionError::new);
		assertTrue(item.getAcceptableIds().contains(BLACK_MASK_10));
		assertTrue("imbued upgrade satisfies plain", item.getAcceptableIds().contains(BLACK_MASK_I));
		assertTrue(item.getAcceptableIds().contains(BLACK_MASK_10_I));
	}

	@Test
	public void recolorsSatisfyButPlainDoesNotSatisfyImbued()
	{
		ItemResolver r = resolver(
			SLAYER_HELMET, "Slayer helmet",
			SLAYER_HELMET_I, "Slayer helmet (i)",
			BLACK_SLAYER_HELMET, "Black slayer helmet",
			BLACK_SLAYER_HELMET_I, "Black slayer helmet (i)");
		ResolvedItem item = r.resolve("Slayer helmet (i)").orElseThrow(AssertionError::new);
		assertTrue("recolored imbued satisfies imbued", item.getAcceptableIds().contains(BLACK_SLAYER_HELMET_I));
		assertFalse("plain must not satisfy imbued", item.getAcceptableIds().contains(SLAYER_HELMET));
		assertFalse("recolored plain must not satisfy imbued", item.getAcceptableIds().contains(BLACK_SLAYER_HELMET));
	}

	@Test
	public void whipRecolorsAccepted()
	{
		ItemResolver r = resolver(
			ABYSSAL_WHIP, "Abyssal whip",
			VOLCANIC_ABYSSAL_WHIP, "Volcanic abyssal whip",
			FROZEN_ABYSSAL_WHIP, "Frozen abyssal whip");
		ResolvedItem item = r.resolve("Abyssal whip").orElseThrow(AssertionError::new);
		assertTrue(item.getAcceptableIds().contains(VOLCANIC_ABYSSAL_WHIP));
		assertTrue(item.getAcceptableIds().contains(FROZEN_ABYSSAL_WHIP));
	}

	@Test
	public void nameMatchingIsCaseAndWhitespaceInsensitive()
	{
		ItemResolver r = resolver(ABYSSAL_WHIP, "Abyssal whip");
		assertTrue(r.resolve("  abyssal   WHIP ").isPresent());
	}

	@Test
	public void unknownNameResolvesEmpty()
	{
		ItemResolver r = resolver(ABYSSAL_WHIP, "Abyssal whip");
		assertFalse(r.resolve("Sword of a thousand truths").isPresent());
	}

	@Test
	public void wikiDisambiguatorSuffixIsRetriedWithoutParenthetical()
	{
		int houseTab = 8013;
		ItemResolver r = resolver(houseTab, "Teleport to house");
		ResolvedItem item = r.resolve("Teleport to house (tablet)").orElseThrow(AssertionError::new);
		assertEquals(houseTab, item.getPrimaryId());
	}

	@Test
	public void meaningfulParentheticalsAreNotStrippedWhenTheyResolve()
	{
		// "(i)" resolves directly — the fallback must not kick in and widen the match
		ItemResolver r = resolver(
			BLACK_MASK, "Black mask",
			BLACK_MASK_I, "Black mask (i)");
		assertEquals(BLACK_MASK_I, (int) r.resolve("Black mask (i)").orElseThrow(AssertionError::new).getPrimaryId());
	}

	@Test
	public void divineRunePouchSatisfiesRunePouchRecommendation()
	{
		ItemResolver r = resolver(
			12791, "Rune pouch",
			27281, "Divine rune pouch");
		ResolvedItem item = r.resolve("Rune pouch").orElseThrow(AssertionError::new);
		assertEquals(12791, item.getPrimaryId());
		assertTrue("divine upgrade satisfies rune pouch", item.getAcceptableIds().contains(27281));
	}

	@Test
	public void imbuedGodCapeGenericAcceptsAnyGodCape()
	{
		ItemResolver r = resolver(
			21791, "Imbued saradomin cape",
			21793, "Imbued guthix cape",
			21795, "Imbued zamorak cape");
		ResolvedItem item = r.resolve("Imbued god cape").orElseThrow(AssertionError::new);
		assertTrue(item.getAcceptableIds().contains(21791));
		assertTrue(item.getAcceptableIds().contains(21793));
		assertTrue(item.getAcceptableIds().contains(21795));
	}

	@Test
	public void potionNameWithoutDoseResolvesToFourDose()
	{
		ItemResolver r = resolver(12625, "Stamina potion(4)");
		ResolvedItem item = r.resolve("Stamina potion").orElseThrow(AssertionError::new);
		assertEquals(12625, item.getPrimaryId());
	}

	@Test
	public void quantityMarkersAreStripped()
	{
		ItemResolver r = resolver(ABYSSAL_WHIP, "Abyssal whip", 385, "Shark");
		assertTrue(r.resolve("2 x Shark").isPresent());
		assertTrue(r.resolve("Shark x28").isPresent());
	}

	@Test
	public void pluralNameFallsBackToSingular()
	{
		ItemResolver r = resolver(385, "Shark");
		assertTrue(r.resolve("Sharks").isPresent());
	}

	@Test
	public void parenSpacingDifferencesAreNormalizedAway()
	{
		// the game says "Salve amulet(ei)", the wiki says "Salve amulet (ei)"
		ItemResolver r = resolver(12018, "Salve amulet(ei)");
		assertTrue(r.resolve("Salve amulet (ei)").isPresent());
	}

	@Test
	public void blazingBlowpipeSatisfiesToxicBlowpipe()
	{
		ItemResolver r = resolver(
			12926, "Toxic blowpipe",
			30374, "Blazing blowpipe");
